insert into didactic_payload values ($didactic_b60776e4783f9939${"version":1,"reviewed_at":"2026-10-25T03:23:26.419620+00:00","actor":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","topic":{"id":"5873244d-48e6-4241-a474-b5db3317d27f","block_name":"Bloco I","created_at":"2026-09-26T03:57:09.233726+00:00","discipline":"Língua Portuguesa","edition_id":"a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff","topic_text":"Estrutura morfossintática do período: classes de palavras; coordenação e subordinação entre orações e termos; pontuação; concordância verbal e nominal; regência verbal e nominal; crase; colocação dos pronomes átonos.","topic_order":2,"content_status":"current"},"topics":{"texto":{"id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","block_name":"Bloco I","created_at":"2026-09-26T03:57:09.233726+00:00","discipline":"Língua Portuguesa","edition_id":"a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff","topic_text":"Compreensão e interpretação de textos de gêneros variados; reconhecimento de tipos e gêneros textuais; domínio da ortografia oficial e dos mecanismos de coesão textual; referenciação, substituição, repetição, conectores e sequenciação; tempos e modos verbais.","topic_order":1,"content_status":"current"},"gramatica":{"id":"5873244d-48e6-4241-a474-b5db3317d27f","block_name":"Bloco I","created_at":"2026-09-26T03:57:09.233726+00:00","discipline":"Língua Portuguesa","edition_id":"a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff","topic_text":"Estrutura morfossintática do período: classes de palavras; coordenação e subordinação entre orações e termos; pontuação; concordância verbal e nominal; regência verbal e nominal; crase; colocação dos pronomes átonos.","topic_order":2,"content_status":"current"},"reescrita":{"id":"13a80069-1852-447d-a71b-1c8f2489c487","block_name":"Bloco I","created_at":"2026-09-26T03:57:09.233726+00:00","discipline":"Língua Portuguesa","edition_id":"a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff","topic_text":"Reescrita de frases e parágrafos: significação das palavras; substituição de palavras ou trechos; reorganização de orações e períodos; reescrita em diferentes gêneros e níveis de formalidade. Correspondência oficial conforme o Manual de Redação da Presidência: aspectos gerais, finalidades, linguagem e formato.","topic_order":3,"content_status":"current"}},"sources":[{"key":"acordo","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","requested_url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","bytes":188111,"sha256":"61e5838b2921bd8379366e1d6cf356d11da62823f33504bb563aa91e868c97be","checked_at":"2026-10-25T02:44:55.441492+00:00","title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","status":"vigente","is_official":true,"source_type":"decreto","issuer":"Presidência da República — Planalto"},{"key":"d9758","url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/decreto/d9758.htm","requested_url":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/decreto/d9758.htm","bytes":24445,"sha256":"51a006ceef1ebc05b2df7b26e4b92ae8ad215a5f91cc3b4a4c548d1a6f712aff","checked_at":"2026-10-25T02:44:53.247984+00:00","title":"Decreto 9.758/2019 — formas de tratamento na administração federal","id":"683b9e4f-82d9-5260-b1f8-05835edd0fad","status":"vigente","is_official":true,"source_type":"decreto","issuer":"Presidência da República — Planalto"},{"key":"simples","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15263.htm","requested_url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15263.htm","bytes":23755,"sha256":"02913b7878a102065327dfd6311a16963177d07d713d4e64fcc738836430a165","checked_at":"2026-10-25T02:44:54.076624+00:00","title":"Lei 15.263/2025 — Política Nacional de Linguagem Simples","id":"a16f97a9-7481-5d77-9bf8-3da8b0599e2d","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"concordancia","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/concordancia-verbal","sha256":"0ce86a5c31bae99702af0e93eace32547442022cfd7f3a310108b4e2097a808e","checked_at":"2026-10-25T02:47:55.585610+00:00","bytes":26884,"title":"Senado Federal — concordância verbal","id":"421bb930-7b5a-5f24-9597-651fbf2ba62e","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"key":"crase","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/crase","sha256":"a68488bead83950f65170fa13713bf47a69aea64bf894b4d05262bd50e65dbe1","checked_at":"2026-10-25T02:47:56.606572+00:00","bytes":24413,"title":"Senado Federal — crase","id":"1e2fd682-059c-5a08-b8ed-416cc61441fc","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"key":"virgula","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/virgula","sha256":"149b64227e4d08c429f1ac80c58db59cc85cc545e3d5a1a7ca3fef750fa7d438","checked_at":"2026-10-25T02:49:16.178595+00:00","bytes":21809,"title":"Senado Federal — uso da vírgula","id":"f86cce8d-00f6-5d75-87db-fd05ef272a07","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","bytes":24352,"sha256":"c9d716829969122d7e63a48e49c127f81993a55dc2c343b0a1fb44889ccce03b","checked_at":"2026-10-25T03:07:02.833711+00:00","key":"gramatica","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","id":"8839c291-1d0d-554e-b02a-72a35ac278b4","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"}],"counts":{"needs_review":94,"duplicate_reused":3,"published":105},"rows":[{"input_index":0,"statement":"Identifique abaixo as afirmativas verdadeiras ( V ) e as falsas ( F ), conforme o texto 1. ( ) Trata-se de um texto predominantemente narrativo, o que se evidencia pelo uso de tempos verbais passados e pela espacialização do enredo. ( ) O texto traz elementos predominantemente argumentativos, com posicionamentos explícitos do autor em relação ao tema. ( ) Trata-se de um texto descritivo, neutro e relativista, em que predominam exemplos factuais e culturalmente contextualizados. ( ) O texto é anacrônico e generalista, não podendo ser tomado como referência explicativa para a conjuntura moderna. ( ) O uso de adjetivos como “pouquíssima”, “privilegiado”, “extraordinária” e “consideráveis” (segundo parágrafo) revela uma atitude avaliativa do autor. Assinale a alternativa que indica a sequência correta, de cima para baixo.\n(A) V • V • V • F • F\n(B) V • F • F • V • V\n(C) V • F • F • F • V\n(D) F • V • V • V • F\n(E) F • V • F • F • V Um dos principais desafios para o Brasil é conhecer a Amazônia. Sua vocação eminentemente hídrica impõe, ao longo dos séculos, a necessidade do deslocamento de seus 4 habitantes através dos rios. Muito antes da chegada dos colonizadores na Amazônia, os nativos já utilizavam canoas. Ainda hoje, grande parte da população amazônica vive da 7 pesca. Além disso, o deslocamento do ribeirinho se faz através da infinidade de rios que retalham a grandeza territorial. Mas para conhecer a Amazônia de verdade é preciso 10 entender sua posição estratégica para o país. Os rios são a chave para esse conhecimento. São as estradas que a natureza construiu e em cujas margens se desenvolveram inúmeras 13 povoações. Portanto, é impossível pensar em Amazônia sem associar a importância que os rios têm para o desenvolvimento econômico e social. Eles devem ser vistos como os grandes 16 propulsores do desenvolvimento sustentável da região. Domingos Savio Almeida Nogueira. In: Internet: (com adaptações) Em relação ao texto acima, julgue o item a seguir.","content_fingerprint":"identifique abaixo as afirmativas verdadeiras v e as falsas f conforme o texto 1 trata se de um texto predominantemente narrativo o que se evidencia pelo uso de tempos verbais passados e pela espacializacao do enredo o texto traz elementos predominantemente argumentativos com posicionamentos explicitos do autor em relacao ao tema trata se de um texto descritivo neutro e relativista em que predominam exemplos factuais e culturalmente contextualizados o texto e anacronico e generalista nao podendo ser tomado como referencia explicativa para a conjuntura moderna o uso de adjetivos como pouquissima privilegiado extraordinaria e consideraveis segundo paragrafo revela uma atitude avaliativa do autor assinale a alternativa que indica a sequencia correta de cima para baixo a v v v f f b v f f v v c v f f f v d f v v v f e f v f f v um dos principais desafios para o brasil e conhecer a amazonia sua vocacao eminentemente hidrica impoe ao longo dos seculos a necessidade do deslocamento de seus 4 habitantes atraves dos rios muito antes da chegada dos colonizadores na amazonia os nativos ja utilizavam canoas ainda hoje grande parte da populacao amazonica vive da 7 pesca alem disso o deslocamento do ribeirinho se faz atraves da infinidade de rios que retalham a grandeza territorial mas para conhecer a amazonia de verdade e preciso 10 entender sua posicao estrategica para o pais os rios sao a chave para esse conhecimento sao as estradas que a natureza construiu e em cujas margens se desenvolveram inumeras 13 povoacoes portanto e impossivel pensar em amazonia sem associar a importancia que os rios tem para o desenvolvimento economico e social eles devem ser vistos como os grandes 16 propulsores do desenvolvimento sustentavel da regiao domingos savio almeida nogueira in internet com adaptacoes em relacao ao texto acima julgue o item a seguir","audit":{"id":"6d9b4ff2-dd25-522f-92b3-5f314cc7ffc8","document_sha256":"78a8c2238bfe60f9d02b2814e927cdafcbc17e61326bb2c131b3b1c3bbd88c56","document_name":"01-01_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":1,"extracted_statement":"Identifique abaixo as afirmativas verdadeiras ( V ) e as falsas ( F ), conforme o texto 1. ( ) Trata-se de um texto predominantemente narrativo, o que se evidencia pelo uso de tempos verbais passados e pela espacialização do enredo. ( ) O texto traz elementos predominantemente argumentativos, com posicionamentos explícitos do autor em relação ao tema. ( ) Trata-se de um texto descritivo, neutro e relativista, em que predominam exemplos factuais e culturalmente contextualizados. ( ) O texto é anacrônico e generalista, não podendo ser tomado como referência explicativa para a conjuntura moderna. ( ) O uso de adjetivos como “pouquíssima”, “privilegiado”, “extraordinária” e “consideráveis” (segundo parágrafo) revela uma atitude avaliativa do autor. Assinale a alternativa que indica a sequência correta, de cima para baixo. a) V • V • V • F • F b) V • F • F • V • V c) V • F • F • F • V d) F • V • V • V • F e) F • V • F • F • V Um dos principais desafios para o Brasil é conhecer a Amazônia. Sua vocação eminentemente hídrica impõe, ao longo dos séculos, a necessidade do deslocamento de seus 4 habitantes através dos rios. Muito antes da chegada dos colonizadores na Amazônia, os nativos já utilizavam canoas. Ainda hoje, grande parte da população amazônica vive da 7 pesca. Além disso, o deslocamento do ribeirinho se faz através da infinidade de rios que retalham a grandeza territorial. Mas para conhecer a Amazônia de verdade é preciso 10 entender sua posição estratégica para o país. Os rios são a chave para esse conhecimento. São as estradas que a natureza construiu e em cujas margens se desenvolveram inúmeras 13 povoações. Portanto, é impossível pensar em Amazônia sem associar a importância que os rios têm para o desenvolvimento econômico e social. Eles devem ser vistos como os grandes 16 propulsores do desenvolvimento sustentável da região. Domingos Savio Almeida Nogueira. In: Internet: (com adaptações) Em relação ao texto acima, julgue o item a seguir.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":1,"statement":"Predomina no texto a narração, já que nele se identificam um cenário e uma ação.","content_fingerprint":"predomina no texto a narracao ja que nele se identificam um cenario e uma acao","audit":{"id":"57a655dd-3755-57bc-8731-82f6b6cef808","document_sha256":"78a8c2238bfe60f9d02b2814e927cdafcbc17e61326bb2c131b3b1c3bbd88c56","document_name":"01-01_lingua_portuguesa_giancarla_bombonato.pdf","source_page":5,"item_number":2,"extracted_statement":"Predomina no texto a narração, já que nele se identificam um cenário e uma ação.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":2,"statement":"Assinale a alternativa em que o termo em destaque está empregado em sentido figurado.\n(A) ... dar aos réus todas as possibilidades recursais...\n(B) ... médicos conduzindo pessoalmente cada etapa dos processos diagnóstico e terapêutico...\n(C) Aqui, seria preciso redesenhar os sistemas...\n(D) ... quando alternativas que dessem conta dos casos mais simples tivessem se esgotado.\n(E) É perfeitamente possível e desejável utilizar outros profissionais... Ao ser promulgada a atual Constituição Federal, em 1988, o país contava com 4.180 municípios. Coerentemente com os ventos liberalizantes da época, a transformação de distritos em cidades dependia, em princípio, de parecer da assembleia legislativa do estado respectivo. Nada difícil, pois o surgimento miraculoso de prefeituras (e estados) frequentemente interessa a políticos regionais, alguns deles especialistas em exercitar o empreguismo e o clientelismo. Foi assim que, a partir de 1988, brotaram outras 1.400 prefeituras, até essa indústria ser fechada por emenda constitucional, em 1996, que passou para o Congresso a prerrogativa de permitir plebiscitos sobre novos entes federativos. O Globo, 5/3/2014 (com adaptações)","content_fingerprint":"assinale a alternativa em que o termo em destaque esta empregado em sentido figurado a dar aos reus todas as possibilidades recursais b medicos conduzindo pessoalmente cada etapa dos processos diagnostico e terapeutico c aqui seria preciso redesenhar os sistemas d quando alternativas que dessem conta dos casos mais simples tivessem se esgotado e e perfeitamente possivel e desejavel utilizar outros profissionais ao ser promulgada a atual constituicao federal em 1988 o pais contava com 4 180 municipios coerentemente com os ventos liberalizantes da epoca a transformacao de distritos em cidades dependia em principio de parecer da assembleia legislativa do estado respectivo nada dificil pois o surgimento miraculoso de prefeituras e estados frequentemente interessa a politicos regionais alguns deles especialistas em exercitar o empreguismo e o clientelismo foi assim que a partir de 1988 brotaram outras 1 400 prefeituras ate essa industria ser fechada por emenda constitucional em 1996 que passou para o congresso a prerrogativa de permitir plebiscitos sobre novos entes federativos o globo 5 3 2014 com adaptacoes","audit":{"id":"c183a069-9df5-5201-8ea8-7a632d1f7a53","document_sha256":"4a29922ccfae3a39ed19ae8125d8d07b649a5ce0eeb0cda92dfbeb034a04b504","document_name":"01-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":3,"item_number":1,"extracted_statement":"Assinale a alternativa em que o termo em destaque está empregado em sentido figurado. a) ... dar aos réus todas as possibilidades recursais... b) ... médicos conduzindo pessoalmente cada etapa dos processos diagnóstico e terapêutico... c) Aqui, seria preciso redesenhar os sistemas... d) ... quando alternativas que dessem conta dos casos mais simples tivessem se esgotado. e) É perfeitamente possível e desejável utilizar outros profissionais... Ao ser promulgada a atual Constituição Federal, em 1988, o país contava com 4.180 municípios. Coerentemente com os ventos liberalizantes da época, a transformação de distritos em cidades dependia, em princípio, de parecer da assembleia legislativa do estado respectivo. Nada difícil, pois o surgimento miraculoso de prefeituras (e estados) frequentemente interessa a políticos regionais, alguns deles especialistas em exercitar o empreguismo e o clientelismo. Foi assim que, a partir de 1988, brotaram outras 1.400 prefeituras, até essa indústria ser fechada por emenda constitucional, em 1996, que passou para o Congresso a prerrogativa de permitir plebiscitos sobre novos entes federativos. O Globo, 5/3/2014 (com adaptações)","provided_answer":"C","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":3,"statement":"No texto acima, está sendo empregado em sentido denotativo o termo\n(A) “brotaram”\n(B) “indústria”\n(C) “ventos”\n(D) “miraculoso”\n(E) “regionais” Pavio do destino Sérgio Sampaio (L . 01) O bandido e o mocinho São os dois do mesmo ninho Correm nos estreitos trilhos (L . 04) Lá no morro dos aflitos Na Favela do Esqueleto São filhos do primo pobre (L . 07) A parcela do silêncio Que encobre todos os gritos E vão caminhando juntos (L . 10) O mocinho e o bandido De revólver de brinquedo Porque ainda são meninos (L . 13) Quem viu o pavio aceso do destino? Com um pouco mais de idade E já não são como antes (L . 16) Depois que uma autoridade Inventou-lhes um flagrante Quanto mais escapa o tempo (L . 19) Dos falsos educandários Mais a dor é o documento Que os agride e os separa (L . 22) Não são mais dois inocentes Não se falam cara a cara Quem pode escapar ileso (L . 25) Do medo e do desatino Quem viu o pavio aceso do destino? O tempo é pai de tudo (L . 28 ) E surpresa não tem dia Pode ser que haja no mundo Outra maior ironia (L . 31) O bandido veste a farda Da suprema segurança O mocinho agora amarga (L . 34) Um bando, uma quadrilha São os dois da mesma safra Os dois são da mesma ilha (L . 37) Dois meninos pelo avesso Dois perdidos Valentinos Quem viu o pavio aceso do destino?","content_fingerprint":"no texto acima esta sendo empregado em sentido denotativo o termo a brotaram b industria c ventos d miraculoso e regionais pavio do destino sergio sampaio l 01 o bandido e o mocinho sao os dois do mesmo ninho correm nos estreitos trilhos l 04 la no morro dos aflitos na favela do esqueleto sao filhos do primo pobre l 07 a parcela do silencio que encobre todos os gritos e vao caminhando juntos l 10 o mocinho e o bandido de revolver de brinquedo porque ainda sao meninos l 13 quem viu o pavio aceso do destino com um pouco mais de idade e ja nao sao como antes l 16 depois que uma autoridade inventou lhes um flagrante quanto mais escapa o tempo l 19 dos falsos educandarios mais a dor e o documento que os agride e os separa l 22 nao sao mais dois inocentes nao se falam cara a cara quem pode escapar ileso l 25 do medo e do desatino quem viu o pavio aceso do destino o tempo e pai de tudo l 28 e surpresa nao tem dia pode ser que haja no mundo outra maior ironia l 31 o bandido veste a farda da suprema seguranca o mocinho agora amarga l 34 um bando uma quadrilha sao os dois da mesma safra os dois sao da mesma ilha l 37 dois meninos pelo avesso dois perdidos valentinos quem viu o pavio aceso do destino","audit":{"id":"984728e3-57a7-562f-b7fc-9f1f526e4cc0","document_sha256":"4a29922ccfae3a39ed19ae8125d8d07b649a5ce0eeb0cda92dfbeb034a04b504","document_name":"01-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":2,"extracted_statement":"No texto acima, está sendo empregado em sentido denotativo o termo a) “brotaram” b) “indústria” c) “ventos” d) “miraculoso” e) “regionais” Pavio do destino Sérgio Sampaio (L . 01) O bandido e o mocinho São os dois do mesmo ninho Correm nos estreitos trilhos (L . 04) Lá no morro dos aflitos Na Favela do Esqueleto São filhos do primo pobre (L . 07) A parcela do silêncio Que encobre todos os gritos E vão caminhando juntos (L . 10) O mocinho e o bandido De revólver de brinquedo Porque ainda são meninos (L . 13) Quem viu o pavio aceso do destino? Com um pouco mais de idade E já não são como antes (L . 16) Depois que uma autoridade Inventou-lhes um flagrante Quanto mais escapa o tempo (L . 19) Dos falsos educandários Mais a dor é o documento Que os agride e os separa (L . 22) Não são mais dois inocentes Não se falam cara a cara Quem pode escapar ileso (L . 25) Do medo e do desatino Quem viu o pavio aceso do destino? O tempo é pai de tudo (L . 28 ) E surpresa não tem dia Pode ser que haja no mundo Outra maior ironia (L . 31) O bandido veste a farda Da suprema segurança O mocinho agora amarga (L . 34) Um bando, uma quadrilha São os dois da mesma safra Os dois são da mesma ilha (L . 37) Dois meninos pelo avesso Dois perdidos Valentinos Quem viu o pavio aceso do destino?","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":4,"statement":"Os termos “ninho” (v.2) e “safra” (v.35) foram empregados em sentido denotativo e correspondem, respectivamente, ao local e à época de nascimento dos meninos. Robustecer os orçamentos da educação e da saúde constitui sonho acalentado por brasileiros, independentemente de opção partidária ou credo religioso. As duas áreas — os 4 mais dolorosos problemas que dificultam a marcha do país rumo ao desenvolvimento sustentável — clamam por melhorias urgentes. Não é outra a razão por que milhares de 7 pessoas ocuparam as ruas das mais importantes unidades da Federação exigindo escolas e hospitais padrão FIFA. Correio Braziliense, 18/8/2013 (com adaptações)","content_fingerprint":"os termos ninho v 2 e safra v 35 foram empregados em sentido denotativo e correspondem respectivamente ao local e a epoca de nascimento dos meninos robustecer os orcamentos da educacao e da saude constitui sonho acalentado por brasileiros independentemente de opcao partidaria ou credo religioso as duas areas os 4 mais dolorosos problemas que dificultam a marcha do pais rumo ao desenvolvimento sustentavel clamam por melhorias urgentes nao e outra a razao por que milhares de 7 pessoas ocuparam as ruas das mais importantes unidades da federacao exigindo escolas e hospitais padrao fifa correio braziliense 18 8 2013 com adaptacoes","audit":{"id":"524d19cc-f191-5dc0-811a-eb6bf7534d13","document_sha256":"4a29922ccfae3a39ed19ae8125d8d07b649a5ce0eeb0cda92dfbeb034a04b504","document_name":"01-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":5,"item_number":3,"extracted_statement":"Os termos “ninho” (v.2) e “safra” (v.35) foram empregados em sentido denotativo e correspondem, respectivamente, ao local e à época de nascimento dos meninos. Robustecer os orçamentos da educação e da saúde constitui sonho acalentado por brasileiros, independentemente de opção partidária ou credo religioso. As duas áreas — os 4 mais dolorosos problemas que dificultam a marcha do país rumo ao desenvolvimento sustentável — clamam por melhorias urgentes. Não é outra a razão por que milhares de 7 pessoas ocuparam as ruas das mais importantes unidades da Federação exigindo escolas e hospitais padrão FIFA. Correio Braziliense, 18/8/2013 (com adaptações)","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":5,"statement":"A expressão “padrão FIFA” (l.8) está sendo empregada com o sentido de qualidade excelente.","content_fingerprint":"a expressao padrao fifa l 8 esta sendo empregada com o sentido de qualidade excelente","audit":{"id":"04295df3-c807-5584-bd6e-863a171bb018","document_sha256":"4a29922ccfae3a39ed19ae8125d8d07b649a5ce0eeb0cda92dfbeb034a04b504","document_name":"01-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":5,"item_number":4,"extracted_statement":"A expressão “padrão FIFA” (l.8) está sendo empregada com o sentido de qualidade excelente.","provided_answer":"C","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":6,"statement":"Infere-se da leitura do texto que:\n(A) o Brasil é o país mais atrasado, entre as democracias, no que diz respeito à garantia dos direitos fundamentais dos cidadãos;\n(B) sem os direitos políticos, civis, econômicos, sociais e culturais, a vida em sociedade seria impossível;\n(C) o voto feminino no Brasil exemplifica um direito político de quarta geração, só conseguido com esforço e luta;\n(D) a sociedade mudou profundamente a partir da conquista do voto feminino no Brasil;\n(E) sem esforço e luta, os direitos fundamentais dos cidadãos estariam inscritos nas Constituições, mas sem aplicação social. Leia o texto a seguir. Os direitos “nossos” e os “deles” Não é incomum que julguemos o que chamamos “nossos” direitos superiores aos direitos do “outro”. Tanto no nível mais pessoal das relações como nos fatos sociais costuma ocorrer essa discrepância, com as consequências de sempre: soluções injustas. Durante um júri, em que defendia um escravo que havia matado o seu senhor, Luís Gama (1830 - 1882), advogado, jornalista e escritor mestiço, abolicionista que chegou a ser escravo por alguns anos, proferiu uma frase que se tornou célebre, numa sessão de julgamento: “O escravo que mata o senhor, seja em que circunstância for, mata sempre em legítima defesa”. A frase causou tumulto e acabou por suspender a sessão do júri, despertando tremenda polêmica à época. Na verdade, continua provocando. Dissesse alguém isso hoje, em alguma circunstância análoga, seria aplaudido por uns e acusado por outros de demonizar o “proprietário”. Como se vê, também a demonização tem duas mãos: os partidários de quem subjuga acabam por demonizar a reação do subjugado. Tais fatos e tais polêmicas, sobre tais direitos, nem deveriam existir, mas existem; será que terão fim? O grande pensador e militante italiano Antonio Gramsci (1891-1937), que passou muitos anos na prisão por conta de suas ideias socialistas, propunha, em algum lugar de sua obra, que diante do dilema de uma escolha nossa conduta subsequente deve se reger pela avaliação objetiva das circunstâncias para então responder à seguinte pergunta: “Quem sofre?” Para Gramsci, o sofrimento humano é um parâmetro que não se pode perder de vista na avaliação das decisões pessoais ou políticas. (Abelardo Trancoso, inédito)","content_fingerprint":"infere se da leitura do texto que a o brasil e o pais mais atrasado entre as democracias no que diz respeito a garantia dos direitos fundamentais dos cidadaos b sem os direitos politicos civis economicos sociais e culturais a vida em sociedade seria impossivel c o voto feminino no brasil exemplifica um direito politico de quarta geracao so conseguido com esforco e luta d a sociedade mudou profundamente a partir da conquista do voto feminino no brasil e sem esforco e luta os direitos fundamentais dos cidadaos estariam inscritos nas constituicoes mas sem aplicacao social leia o texto a seguir os direitos nossos e os deles nao e incomum que julguemos o que chamamos nossos direitos superiores aos direitos do outro tanto no nivel mais pessoal das relacoes como nos fatos sociais costuma ocorrer essa discrepancia com as consequencias de sempre solucoes injustas durante um juri em que defendia um escravo que havia matado o seu senhor luis gama 1830 1882 advogado jornalista e escritor mestico abolicionista que chegou a ser escravo por alguns anos proferiu uma frase que se tornou celebre numa sessao de julgamento o escravo que mata o senhor seja em que circunstancia for mata sempre em legitima defesa a frase causou tumulto e acabou por suspender a sessao do juri despertando tremenda polemica a epoca na verdade continua provocando dissesse alguem isso hoje em alguma circunstancia analoga seria aplaudido por uns e acusado por outros de demonizar o proprietario como se ve tambem a demonizacao tem duas maos os partidarios de quem subjuga acabam por demonizar a reacao do subjugado tais fatos e tais polemicas sobre tais direitos nem deveriam existir mas existem sera que terao fim o grande pensador e militante italiano antonio gramsci 1891 1937 que passou muitos anos na prisao por conta de suas ideias socialistas propunha em algum lugar de sua obra que diante do dilema de uma escolha nossa conduta subsequente deve se reger pela avaliacao objetiva das circunstancias para entao responder a seguinte pergunta quem sofre para gramsci o sofrimento humano e um parametro que nao se pode perder de vista na avaliacao das decisoes pessoais ou politicas abelardo trancoso inedito","audit":{"id":"4ed797bd-4920-521b-82c8-1283c58b8308","document_sha256":"2eaeace0fab913e2fba6fcebd71f97b8064b4d3d017f6751f8b5379b4648f017","document_name":"01-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":1,"extracted_statement":"Infere-se da leitura do texto que: a) o Brasil é o país mais atrasado, entre as democracias, no que diz respeito à garantia dos direitos fundamentais dos cidadãos; b) sem os direitos políticos, civis, econômicos, sociais e culturais, a vida em sociedade seria impossível; c) o voto feminino no Brasil exemplifica um direito político de quarta geração, só conseguido com esforço e luta; d) a sociedade mudou profundamente a partir da conquista do voto feminino no Brasil; e) sem esforço e luta, os direitos fundamentais dos cidadãos estariam inscritos nas Constituições, mas sem aplicação social. Leia o texto a seguir. Os direitos “nossos” e os “deles” Não é incomum que julguemos o que chamamos “nossos” direitos superiores aos direitos do “outro”. Tanto no nível mais pessoal das relações como nos fatos sociais costuma ocorrer essa discrepância, com as consequências de sempre: soluções injustas. Durante um júri, em que defendia um escravo que havia matado o seu senhor, Luís Gama (1830 - 1882), advogado, jornalista e escritor mestiço, abolicionista que chegou a ser escravo por alguns anos, proferiu uma frase que se tornou célebre, numa sessão de julgamento: “O escravo que mata o senhor, seja em que circunstância for, mata sempre em legítima defesa”. A frase causou tumulto e acabou por suspender a sessão do júri, despertando tremenda polêmica à época. Na verdade, continua provocando. Dissesse alguém isso hoje, em alguma circunstância análoga, seria aplaudido por uns e acusado por outros de demonizar o “proprietário”. Como se vê, também a demonização tem duas mãos: os partidários de quem subjuga acabam por demonizar a reação do subjugado. Tais fatos e tais polêmicas, sobre tais direitos, nem deveriam existir, mas existem; será que terão fim? O grande pensador e militante italiano Antonio Gramsci (1891-1937), que passou muitos anos na prisão por conta de suas ideias socialistas, propunha, em algum lugar de sua obra, que diante do dilema de uma escolha nossa conduta subsequente deve se reger pela avaliação objetiva das circunstâncias para então responder à seguinte pergunta: “Quem sofre?” Para Gramsci, o sofrimento humano é um parâmetro que não se pode perder de vista na avaliação das decisões pessoais ou políticas. (Abelardo Trancoso, inédito)","provided_answer":"C","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":7,"statement":"Deve-se considerar que, na estruturação desse texto, I. o primeiro parágrafo apresenta uma tese com base numa discrepância de valores, que será ilustrada com o fato polêmico exposto no parágrafo seguinte. II. as controvérsias despertadas pela frase proferida por Luís Gama podem ser explicadas pela contundência de um argumento radicalmente abolicionista acionado em pleno regime escravocrata. III. a referência ao militante Antonio Gramsci, no parágrafo final, propicia um argumento poderoso a favor de quem se pauta pelo cumprimento rigoroso da lei, não importando as circunstâncias. Em relação ao texto, é correto o que se considera em\n(A) II e III, apenas.\n(B) I e III, apenas.\n(C) II, apenas.\n(D) I, II e III.\n(E) I e II, apenas.","content_fingerprint":"deve se considerar que na estruturacao desse texto i o primeiro paragrafo apresenta uma tese com base numa discrepancia de valores que sera ilustrada com o fato polemico exposto no paragrafo seguinte ii as controversias despertadas pela frase proferida por luis gama podem ser explicadas pela contundencia de um argumento radicalmente abolicionista acionado em pleno regime escravocrata iii a referencia ao militante antonio gramsci no paragrafo final propicia um argumento poderoso a favor de quem se pauta pelo cumprimento rigoroso da lei nao importando as circunstancias em relacao ao texto e correto o que se considera em a ii e iii apenas b i e iii apenas c ii apenas d i ii e iii e i e ii apenas","audit":{"id":"a171be14-ff28-5a4e-8f20-a2f784658b58","document_sha256":"2eaeace0fab913e2fba6fcebd71f97b8064b4d3d017f6751f8b5379b4648f017","document_name":"01-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":5,"item_number":2,"extracted_statement":"Deve-se considerar que, na estruturação desse texto, I. o primeiro parágrafo apresenta uma tese com base numa discrepância de valores, que será ilustrada com o fato polêmico exposto no parágrafo seguinte. II. as controvérsias despertadas pela frase proferida por Luís Gama podem ser explicadas pela contundência de um argumento radicalmente abolicionista acionado em pleno regime escravocrata. III. a referência ao militante Antonio Gramsci, no parágrafo final, propicia um argumento poderoso a favor de quem se pauta pelo cumprimento rigoroso da lei, não importando as circunstâncias. Em relação ao texto, é correto o que se considera em a) II e III, apenas. b) I e III, apenas. c) II, apenas. d) I, II e III. e) I e II, apenas.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":8,"statement":"Transpondo-se para a voz passiva o segmento sublinhado na frase os partidários de quem subjuga acabam por demonizar a reação do subjugado, ele deverá assumir a seguinte forma:\n(A) acabam demonizando.\n(B) acabam sendo demonizados.\n(C) acabará sendo demonizada.\n(D) acaba por ter sido demonizado.\n(E) acaba por ser demonizada.","content_fingerprint":"transpondo se para a voz passiva o segmento sublinhado na frase os partidarios de quem subjuga acabam por demonizar a reacao do subjugado ele devera assumir a seguinte forma a acabam demonizando b acabam sendo demonizados c acabara sendo demonizada d acaba por ter sido demonizado e acaba por ser demonizada","audit":{"id":"c8cfce29-4f2c-5b40-9d52-5f4cba83cd50","document_sha256":"f17f0c03e9004108db558337fda61666ecba4e6a086b26292b150e449cf95193","document_name":"01-05_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":1,"extracted_statement":"Transpondo-se para a voz passiva o segmento sublinhado na frase os partidários de quem subjuga acabam por demonizar a reação do subjugado, ele deverá assumir a seguinte forma: a) acabam demonizando. b) acabam sendo demonizados. c) acabará sendo demonizada. d) acaba por ter sido demonizado. e) acaba por ser demonizada.","provided_answer":"E","current_answer":"E","review_status":"duplicate_reused","review_note":"Repetição textual exata do exercício revisado do mesmo lote; vínculo à versão com destaque verbal explicitado.","question_table":"curated_question_catalog","question_id":"f7545b4f-a984-5fd7-9000-c6240cf22356","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":null},{"input_index":9,"statement":"O uso indevido de drogas constitui, na atualidade, séria e persistente ameaça à humanidade e à estabilidade das estruturas e valores políticos, econômicos, sociais e culturais de todos os Estados e sociedades. Suas consequências infligem considerável prejuízo às nações do mundo inteiro, e não são detidas por fronteiras.","content_fingerprint":"o uso indevido de drogas constitui na atualidade seria e persistente ameaca a humanidade e a estabilidade das estruturas e valores politicos economicos sociais e culturais de todos os estados e sociedades suas consequencias infligem consideravel prejuizo as nacoes do mundo inteiro e nao sao detidas por fronteiras","audit":{"id":"fec52da9-f396-5a92-86ca-77fac9719610","document_sha256":"4af3f9897bfc3c4a0701eac1367d5623e1b7723211e8d74bc2b879575606d7f9","document_name":"02-01_lingua_portuguesa_giancarla_bombonato.pdf","source_page":3,"item_number":1,"extracted_statement":"O uso indevido de drogas constitui, na atualidade, séria e persistente ameaça à humanidade e à estabilidade das estruturas e valores políticos, econômicos, sociais e culturais de todos os Estados e sociedades. Suas consequências infligem considerável prejuízo às nações do mundo inteiro, e não são detidas por fronteiras.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":10,"statement":"O pronome possessivo “Suas” refere-se a “de todos os Estados e sociedades”.","content_fingerprint":"o pronome possessivo suas refere se a de todos os estados e sociedades","audit":{"id":"44ec7009-3ac9-5513-9f5b-21fa3a0ea0dd","document_sha256":"4af3f9897bfc3c4a0701eac1367d5623e1b7723211e8d74bc2b879575606d7f9","document_name":"02-01_lingua_portuguesa_giancarla_bombonato.pdf","source_page":3,"item_number":2,"extracted_statement":"O pronome possessivo “Suas” refere-se a “de todos os Estados e sociedades”.","provided_answer":"C","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":11,"statement":"Em “Deviam deixar que apodrecesse, para escarmento dos outros homens.” (7º§), pode-se reconhecer a seguinte figura de linguagem:\n(A) Metonímia\n(B) Paradoxo\n(C) Antítese\n(D) Ironia\n(E) Eufemismo Notícia de Jornal (Fernando Sabino) Leio no jornal a notícia de que um homem morreu de fome. Um homem de cor branca, 30 anos presumíveis, pobremente vestido, morreu de fome, sem socorros, em pleno centro da cidade, permanecendo deitado na calçada durante 72 horas, para finalmente morrer de fome. Morreu de fome. Depois de insistentes pedidos e comentários, uma ambulância do Pronto Socorro e uma radiopatrulha foram ao local, mas regressaram sem prestar auxílio ao homem, que acabou morrendo de fome. Um homem que morreu de fome. O comissário de plantão (um homem) afirmou que o caso (morrer de fome) era da alçada da Delegacia de Mendicância, especialista em homens que morrem de fome. E o homem morreu de fome. O corpo do homem que morreu de fome foi recolhido ao Instituto Anatômico sem ser identificado. Nada se sabe dele, senão que morreu de fome. Um homem morre de fome em plena rua, entre centenas de passantes. Um homem caído na rua. Um bêbado. Um vagabundo. Um mendigo, um anormal, um tarado, um pária, um marginal, um proscrito, um bicho, uma coisa - não é um homem. E os outros homens cumprem seu destino de passantes, que é o de passar. Durante setenta e duas horas todos passam, ao lado do homem que morre de fome, com um olhar de nojo, desdém, inquietação e até mesmo piedade, ou sem olhar nenhum. Passam, e o homem continua morrendo de fome, sozinho, isolado, perdido entre os homens, sem socorro e sem perdão. Não é da alçada do comissário, nem do hospital, nem da radiopatrulha, por que haveria de ser da minha alçada? Que é que eu tenho com isso? Deixa o homem morrer de fome. E o homem morre de fome. De trinta anos presumíveis. Pobremente vestido. Morreu de fome, diz o jornal. Louve-se a insistência dos comerciantes, que jamais morrerão de fome, pedindo providências às autoridades. As autoridades nada mais puderam fazer senão remover o corpo do homem. Deviam deixar que apodrecesse, para escarmento dos outros homens. Nada mais puderam fazer senão esperar que morresse de fome. E ontem, depois de setenta e duas horas de inanição, tombado em plena rua, no centro mais movimentado da cidade do Rio de Janeiro, Estado da Guanabara, um homem morreu de fome. (Disponível em http://www.fotolog.com.br/spokesman_/70276847/: Acesso em 10/09/14) Texto II O Bicho (Manuel Bandeira) Vi ontem um bicho Na imundície do pátio Catando comida entre os detritos. Quando achava alguma coisa, Não examinava nem cheirava: Engolia com voracidade. O bicho não era um cão, Não era um gato, Não era um rato. O bicho, meu Deus, era um homem. (Disponível em: http://www.casadobruxo.com.br/poesia/m/bicho.htm, acesso em 10/09/2014)","content_fingerprint":"em deviam deixar que apodrecesse para escarmento dos outros homens 7o pode se reconhecer a seguinte figura de linguagem a metonimia b paradoxo c antitese d ironia e eufemismo noticia de jornal fernando sabino leio no jornal a noticia de que um homem morreu de fome um homem de cor branca 30 anos presumiveis pobremente vestido morreu de fome sem socorros em pleno centro da cidade permanecendo deitado na calcada durante 72 horas para finalmente morrer de fome morreu de fome depois de insistentes pedidos e comentarios uma ambulancia do pronto socorro e uma radiopatrulha foram ao local mas regressaram sem prestar auxilio ao homem que acabou morrendo de fome um homem que morreu de fome o comissario de plantao um homem afirmou que o caso morrer de fome era da alcada da delegacia de mendicancia especialista em homens que morrem de fome e o homem morreu de fome o corpo do homem que morreu de fome foi recolhido ao instituto anatomico sem ser identificado nada se sabe dele senao que morreu de fome um homem morre de fome em plena rua entre centenas de passantes um homem caido na rua um bebado um vagabundo um mendigo um anormal um tarado um paria um marginal um proscrito um bicho uma coisa nao e um homem e os outros homens cumprem seu destino de passantes que e o de passar durante setenta e duas horas todos passam ao lado do homem que morre de fome com um olhar de nojo desdem inquietacao e ate mesmo piedade ou sem olhar nenhum passam e o homem continua morrendo de fome sozinho isolado perdido entre os homens sem socorro e sem perdao nao e da alcada do comissario nem do hospital nem da radiopatrulha por que haveria de ser da minha alcada que e que eu tenho com isso deixa o homem morrer de fome e o homem morre de fome de trinta anos presumiveis pobremente vestido morreu de fome diz o jornal louve se a insistencia dos comerciantes que jamais morrerao de fome pedindo providencias as autoridades as autoridades nada mais puderam fazer senao remover o corpo do homem deviam deixar que apodrecesse para escarmento dos outros homens nada mais puderam fazer senao esperar que morresse de fome e ontem depois de setenta e duas horas de inanicao tombado em plena rua no centro mais movimentado da cidade do rio de janeiro estado da guanabara um homem morreu de fome disponivel em http www fotolog com br spokesman 70276847 acesso em 10 09 14 texto ii o bicho manuel bandeira vi ontem um bicho na imundicie do patio catando comida entre os detritos quando achava alguma coisa nao examinava nem cheirava engolia com voracidade o bicho nao era um cao nao era um gato nao era um rato o bicho meu deus era um homem disponivel em http www casadobruxo com br poesia m bicho htm acesso em 10 09 2014","audit":{"id":"ac58fac5-de6d-5037-be57-ac3adbb05372","document_sha256":"8ba857310a4eda3f2acf2422096936959b15a959dea7d8ffec767bd97e6520b8","document_name":"01-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":7,"item_number":1,"extracted_statement":"Em “Deviam deixar que apodrecesse, para escarmento dos outros homens.” (7º§), pode-se reconhecer a seguinte figura de linguagem: a) Metonímia b) Paradoxo c) Antítese d) Ironia e) Eufemismo Notícia de Jornal (Fernando Sabino) Leio no jornal a notícia de que um homem morreu de fome. Um homem de cor branca, 30 anos presumíveis, pobremente vestido, morreu de fome, sem socorros, em pleno centro da cidade, permanecendo deitado na calçada durante 72 horas, para finalmente morrer de fome. Morreu de fome. Depois de insistentes pedidos e comentários, uma ambulância do Pronto Socorro e uma radiopatrulha foram ao local, mas regressaram sem prestar auxílio ao homem, que acabou morrendo de fome. Um homem que morreu de fome. O comissário de plantão (um homem) afirmou que o caso (morrer de fome) era da alçada da Delegacia de Mendicância, especialista em homens que morrem de fome. E o homem morreu de fome. O corpo do homem que morreu de fome foi recolhido ao Instituto Anatômico sem ser identificado. Nada se sabe dele, senão que morreu de fome. Um homem morre de fome em plena rua, entre centenas de passantes. Um homem caído na rua. Um bêbado. Um vagabundo. Um mendigo, um anormal, um tarado, um pária, um marginal, um proscrito, um bicho, uma coisa - não é um homem. E os outros homens cumprem seu destino de passantes, que é o de passar. Durante setenta e duas horas todos passam, ao lado do homem que morre de fome, com um olhar de nojo, desdém, inquietação e até mesmo piedade, ou sem olhar nenhum. Passam, e o homem continua morrendo de fome, sozinho, isolado, perdido entre os homens, sem socorro e sem perdão. Não é da alçada do comissário, nem do hospital, nem da radiopatrulha, por que haveria de ser da minha alçada? Que é que eu tenho com isso? Deixa o homem morrer de fome. E o homem morre de fome. De trinta anos presumíveis. Pobremente vestido. Morreu de fome, diz o jornal. Louve-se a insistência dos comerciantes, que jamais morrerão de fome, pedindo providências às autoridades. As autoridades nada mais puderam fazer senão remover o corpo do homem. Deviam deixar que apodrecesse, para escarmento dos outros homens. Nada mais puderam fazer senão esperar que morresse de fome. E ontem, depois de setenta e duas horas de inanição, tombado em plena rua, no centro mais movimentado da cidade do Rio de Janeiro, Estado da Guanabara, um homem morreu de fome. (Disponível em http://www.fotolog.com.br/spokesman_/70276847/: Acesso em 10/09/14) Texto II O Bicho (Manuel Bandeira) Vi ontem um bicho Na imundície do pátio Catando comida entre os detritos. Quando achava alguma coisa, Não examinava nem cheirava: Engolia com voracidade. O bicho não era um cão, Não era um gato, Não era um rato. O bicho, meu Deus, era um homem. (Disponível em: http://www.casadobruxo.com.br/poesia/m/bicho.htm, acesso em 10/09/2014)","provided_answer":"D","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":12,"statement":"Tanto na crônica (Texto I) quanto no poema (Texto II) os enunciadores não se limitam a apresentar o fato; eles também buscam causar comoção em seus leitores. A função de linguagem que melhor retrata esse objetivo e os trechos que podem representar esse aspecto são, respectivamente:\n(A) Função metalinguística; “Morreu de Fome” (texto I) e “ Meu Deus” (texto II).\n(B) )Função fática; “Leio no jornal” (texto I ) e “Vi ontem um bicho” (texto II).\n(C) Função poética; “Leio no jornal” (texto I ) e “Vi ontem um bicho” (texto II).\n(D) Função conativa, “Morreu de Fome” (texto I) e “ Meu Deus” (texto II).\n(E) Função referencial; “Um homem de cor branca” (texto I); Na imundície do pátio”” A violência não é uma fantasia A violência nasce conosco. Faz parte da nossa bagagem psíquica, do nosso DNA, assim como a capacidade de cuidar, de ser solidário e pacífico. Somos esse novelo de dons. O equilíbrio ou desequilíbrio depende do ambiente familiar, educação, exemplos, tendência pessoal, circunstâncias concretas, algumas escolhas individuais. Vivemos numa época violenta. Temos medo de sair às ruas, temos medo de sair à noite, temos medo de ficar em casa sem grades, alarmes e câmeras, ou bons e treinados porteiros. As notícias da imprensa nos dão medo em geral. Não são medos fantasiosos: são reais. E, se não tivermos nenhum medo, estaremos sendo perigosamente alienados. A segurança, como tantas coisas, parece ter fugido ao controle de instituições e autoridades. Nestes dias começamos a ter medo também dentro dos shoppings, onde, aliás, há mais tempo aqui e ali vêm ocorrendo furtos, às vezes assaltos, raramente noticiados. O que preocupa são movimentos adolescentes que reivindicam acesso aos shoppings para seus grupos em geral organizados na internet. (...) (Revista Veja. Editora ABRIL. Edição 2358 - ano 47 - nº 5. 29 de janeiro de 2014. Por Lya Luft - p. 20)","content_fingerprint":"tanto na cronica texto i quanto no poema texto ii os enunciadores nao se limitam a apresentar o fato eles tambem buscam causar comocao em seus leitores a funcao de linguagem que melhor retrata esse objetivo e os trechos que podem representar esse aspecto sao respectivamente a funcao metalinguistica morreu de fome texto i e meu deus texto ii b funcao fatica leio no jornal texto i e vi ontem um bicho texto ii c funcao poetica leio no jornal texto i e vi ontem um bicho texto ii d funcao conativa morreu de fome texto i e meu deus texto ii e funcao referencial um homem de cor branca texto i na imundicie do patio a violencia nao e uma fantasia a violencia nasce conosco faz parte da nossa bagagem psiquica do nosso dna assim como a capacidade de cuidar de ser solidario e pacifico somos esse novelo de dons o equilibrio ou desequilibrio depende do ambiente familiar educacao exemplos tendencia pessoal circunstancias concretas algumas escolhas individuais vivemos numa epoca violenta temos medo de sair as ruas temos medo de sair a noite temos medo de ficar em casa sem grades alarmes e cameras ou bons e treinados porteiros as noticias da imprensa nos dao medo em geral nao sao medos fantasiosos sao reais e se nao tivermos nenhum medo estaremos sendo perigosamente alienados a seguranca como tantas coisas parece ter fugido ao controle de instituicoes e autoridades nestes dias comecamos a ter medo tambem dentro dos shoppings onde alias ha mais tempo aqui e ali vem ocorrendo furtos as vezes assaltos raramente noticiados o que preocupa sao movimentos adolescentes que reivindicam acesso aos shoppings para seus grupos em geral organizados na internet revista veja editora abril edicao 2358 ano 47 no 5 29 de janeiro de 2014 por lya luft p 20","audit":{"id":"d4de5876-b0fe-565d-bedb-fd95df1c1141","document_sha256":"8ba857310a4eda3f2acf2422096936959b15a959dea7d8ffec767bd97e6520b8","document_name":"01-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":8,"item_number":2,"extracted_statement":"Tanto na crônica (Texto I) quanto no poema (Texto II) os enunciadores não se limitam a apresentar o fato; eles também buscam causar comoção em seus leitores. A função de linguagem que melhor retrata esse objetivo e os trechos que podem representar esse aspecto são, respectivamente: a) Função metalinguística; “Morreu de Fome” (texto I) e “ Meu Deus” (texto II). b) )Função fática; “Leio no jornal” (texto I ) e “Vi ontem um bicho” (texto II). c) Função poética; “Leio no jornal” (texto I ) e “Vi ontem um bicho” (texto II). d) Função conativa, “Morreu de Fome” (texto I) e “ Meu Deus” (texto II). e) Função referencial; “Um homem de cor branca” (texto I); Na imundície do pátio”” A violência não é uma fantasia A violência nasce conosco. Faz parte da nossa bagagem psíquica, do nosso DNA, assim como a capacidade de cuidar, de ser solidário e pacífico. Somos esse novelo de dons. O equilíbrio ou desequilíbrio depende do ambiente familiar, educação, exemplos, tendência pessoal, circunstâncias concretas, algumas escolhas individuais. Vivemos numa época violenta. Temos medo de sair às ruas, temos medo de sair à noite, temos medo de ficar em casa sem grades, alarmes e câmeras, ou bons e treinados porteiros. As notícias da imprensa nos dão medo em geral. Não são medos fantasiosos: são reais. E, se não tivermos nenhum medo, estaremos sendo perigosamente alienados. A segurança, como tantas coisas, parece ter fugido ao controle de instituições e autoridades. Nestes dias começamos a ter medo também dentro dos shoppings, onde, aliás, há mais tempo aqui e ali vêm ocorrendo furtos, às vezes assaltos, raramente noticiados. O que preocupa são movimentos adolescentes que reivindicam acesso aos shoppings para seus grupos em geral organizados na internet. (...) (Revista Veja. Editora ABRIL. Edição 2358 - ano 47 - nº 5. 29 de janeiro de 2014. Por Lya Luft - p. 20)","provided_answer":"D","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":13,"statement":"A linguagem por meio da qual interagimos no nosso dia a dia pode revestir-se de nuances as mais diversas: pode apresentar-se em sentido literal, figurado, metafórico. A opção em cujo trecho utilizou-se linguagem metafórica é\n(A) O equilíbrio ou desequilíbrio depende do ambiente familiar.\n(B) Temos medo de sair às ruas.\n(C) Nestes dias começamos a ter medo também dentro dos shoppings.\n(D) Somos esse novelo de dons.\n(E) As notícias da imprensa nos dão medo em geral.","content_fingerprint":"a linguagem por meio da qual interagimos no nosso dia a dia pode revestir se de nuances as mais diversas pode apresentar se em sentido literal figurado metaforico a opcao em cujo trecho utilizou se linguagem metaforica e a o equilibrio ou desequilibrio depende do ambiente familiar b temos medo de sair as ruas c nestes dias comecamos a ter medo tambem dentro dos shoppings d somos esse novelo de dons e as noticias da imprensa nos dao medo em geral","audit":{"id":"af86c138-4008-5280-9329-d191ffe9699f","document_sha256":"8ba857310a4eda3f2acf2422096936959b15a959dea7d8ffec767bd97e6520b8","document_name":"01-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":9,"item_number":3,"extracted_statement":"A linguagem por meio da qual interagimos no nosso dia a dia pode revestir-se de nuances as mais diversas: pode apresentar-se em sentido literal, figurado, metafórico. A opção em cujo trecho utilizou-se linguagem metafórica é a) O equilíbrio ou desequilíbrio depende do ambiente familiar. b) Temos medo de sair às ruas. c) Nestes dias começamos a ter medo também dentro dos shoppings. d) Somos esse novelo de dons. e) As notícias da imprensa nos dão medo em geral.","provided_answer":"D","current_answer":"D","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"51de1b8d-35f1-5caa-856e-5a537db0bb68","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"51de1b8d-35f1-5caa-856e-5a537db0bb68","source_id":"8839c291-1d0d-554e-b02a-72a35ac278b4","syllabus_topic_id":"13a80069-1852-447d-a71b-1c8f2489c487","external_item_key":"didactic:8ba857310a4eda3f2acf2422096936959b15a959dea7d8ffec767bd97e6520b8:3","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Semântica e figuras de linguagem","tested_topic":"Semântica e figuras de linguagem","question_text":"A linguagem por meio da qual interagimos no nosso dia a dia pode revestir-se de nuances as mais diversas: pode apresentar-se em sentido literal, figurado, metafórico. A opção em cujo trecho utilizou-se linguagem metafórica é\n(A) O equilíbrio ou desequilíbrio depende do ambiente familiar.\n(B) Temos medo de sair às ruas.\n(C) Nestes dias começamos a ter medo também dentro dos shoppings.\n(D) Somos esse novelo de dons.\n(E) As notícias da imprensa nos dão medo em geral.","official_answer":"D","explanation":"A associação entre pessoas e um novelo de dons é metafórica: não descreve um novelo material. Exemplo de análise: a combinação reúne qualidades numa imagem figurada; a escolha não depende de descobrir um acontecimento externo. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T03:07:02.833711+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"01-04_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Semântica e figuras de linguagem","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"8ba857310a4eda3f2acf2422096936959b15a959dea7d8ffec767bd97e6520b8","page":9,"itemNumber":3,"materialSlug":"portugues-semantica-figuras-linguagem","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":14,"statement":"Para o preenchimento CORRETO das lacunas na frase “A menina não tinha o ________ costume de duvidar da avó, _________, naquele assunto,________ havia terminado a conversa, ela foi perguntar à natureza.”, empregam-se, respectivamente, as formas: \n(A) mau, mais, mal.\n(B) mau, mas, mal.\n(C) mal, mas, mau.\n(D) mal, mais, mal.","content_fingerprint":"para o preenchimento correto das lacunas na frase a menina nao tinha o costume de duvidar da avo naquele assunto havia terminado a conversa ela foi perguntar a natureza empregam se respectivamente as formas a mau mais mal b mau mas mal c mal mas mau d mal mais mal","audit":{"id":"b7a3421c-1835-5b62-88cd-e6c16eb69c77","document_sha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","document_name":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":1,"extracted_statement":"Para o preenchimento CORRETO das lacunas na frase “A menina não tinha o ________ costume de duvidar da avó, _________, naquele assunto,________ havia terminado a conversa, ela foi perguntar à natureza.”, empregam-se, respectivamente, as formas: Parte superior do formulário a) mau, mais, mal. b) mau, mas, mal. c) mal, mas, mau. d) mal, mais, mal.","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"3e917fbc-0a8f-5e4a-9c77-2438dd56537e","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"3e917fbc-0a8f-5e4a-9c77-2438dd56537e","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924:1","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Para o preenchimento CORRETO das lacunas na frase “A menina não tinha o ________ costume de duvidar da avó, _________, naquele assunto,________ havia terminado a conversa, ela foi perguntar à natureza.”, empregam-se, respectivamente, as formas: \n(A) mau, mais, mal.\n(B) mau, mas, mal.\n(C) mal, mas, mau.\n(D) mal, mais, mal.","official_answer":"B","explanation":"Mau caracteriza costume, mas estabelece oposição, e mal pode indicar logo que no contexto temporal. Exemplo: o teste com bom ajuda a reconhecer o adjetivo em mau costume, mas não serve para a conjunção adversativa. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","page":6,"itemNumber":1,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":15,"statement":"Assinale a opção em o emprego do hífen, segundo as regras do mais recente Acordo Ortográfico, está incorreto.\n(A) Vamos comprar um anti-inflamatório porque ela está superresfriada.\n(B) O quadro foi protegido com vidro antirreflexo\n(C) Ele era corréu na acusação de ter assassinado o contrarregra\n(D) O grupo antissequestro já participa da investigação.\n(E) Trata-se de uma informação semioficial.","content_fingerprint":"assinale a opcao em o emprego do hifen segundo as regras do mais recente acordo ortografico esta incorreto a vamos comprar um anti inflamatorio porque ela esta superresfriada b o quadro foi protegido com vidro antirreflexo c ele era correu na acusacao de ter assassinado o contrarregra d o grupo antissequestro ja participa da investigacao e trata se de uma informacao semioficial","audit":{"id":"80debcbc-d297-5049-8e6f-e0d7015e26d2","document_sha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","document_name":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":2,"extracted_statement":"Assinale a opção em o emprego do hífen, segundo as regras do mais recente Acordo Ortográfico, está incorreto. a) Vamos comprar um anti-inflamatório porque ela está superresfriada. b) O quadro foi protegido com vidro antirreflexo c) Ele era corréu na acusação de ter assassinado o contrarregra d) O grupo antissequestro já participa da investigação. e) Trata-se de uma informação semioficial. Leia: ___ um mês, uma turma de operários se posta ___ entrada da fábrica pela manhã e só sai ___ uma hora da tarde. Espera-se que a greve termine daqui ___ uma semana.","provided_answer":"A","current_answer":"A","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"7acc292d-bf54-5cbb-8f08-ffcb7bf433df","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"7acc292d-bf54-5cbb-8f08-ffcb7bf433df","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924:2","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Assinale a opção em o emprego do hífen, segundo as regras do mais recente Acordo Ortográfico, está incorreto.\n(A) Vamos comprar um anti-inflamatório porque ela está superresfriada.\n(B) O quadro foi protegido com vidro antirreflexo\n(C) Ele era corréu na acusação de ter assassinado o contrarregra\n(D) O grupo antissequestro já participa da investigação.\n(E) Trata-se de uma informação semioficial.","official_answer":"A","explanation":"O encontro de super com resfriada exige o hífen na formação super-resfriada. Exemplo: o comportamento de super diante de r não é o mesmo da duplicação em antirreflexo ou antissequestro, que seguem as condições próprias do prefixo. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","page":6,"itemNumber":2,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":16,"statement":"Leia: ___ um mês, uma turma de operários se posta ___ entrada da fábrica pela manhã e só sai ___ uma hora da tarde. Espera-se que a greve termine daqui ___ uma semana. Assinale a alternativa que completa CORRETAMENTE as lacunas da frase acima, na respectivamente ordem.\n(A) Há – à – a – a.\n(B) Há – à – à – a.\n(C) A – a – a – há.\n(D) Há – a – à – há.","content_fingerprint":"leia um mes uma turma de operarios se posta entrada da fabrica pela manha e so sai uma hora da tarde espera se que a greve termine daqui uma semana assinale a alternativa que completa corretamente as lacunas da frase acima na respectivamente ordem a ha a a a b ha a a a c a a a ha d ha a a ha","audit":{"id":"a4bfc5ea-6f88-5b31-926a-21ef604a3109","document_sha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","document_name":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":3,"extracted_statement":"Assinale a alternativa que completa CORRETAMENTE as lacunas da frase acima, na respectivamente ordem. a) Há – à – a – a. b) Há – à – à – a. c) A – a – a – há. d) Há – a – à – há.","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"d3e59915-eefb-557b-adad-8f9a8a08ccf1","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"d3e59915-eefb-557b-adad-8f9a8a08ccf1","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924:3","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Leia: ___ um mês, uma turma de operários se posta ___ entrada da fábrica pela manhã e só sai ___ uma hora da tarde. Espera-se que a greve termine daqui ___ uma semana. Assinale a alternativa que completa CORRETAMENTE as lacunas da frase acima, na respectivamente ordem.\n(A) Há – à – a – a.\n(B) Há – à – à – a.\n(C) A – a – a – há.\n(D) Há – a – à – há.","official_answer":"B","explanation":"Há indica tempo decorrido, à entrada e à uma hora apresentam construções com crase no contexto, e daqui a uma semana indica tempo futuro. Exemplo: substituir o último a por há misturaria projeção futura com tempo já decorrido. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","page":6,"itemNumber":3,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":17,"statement":"Está correto o emprego de ambos os elementos sublinhados em:\n(A) Se o por quê da importância primitiva de Paraty estava na sua localização estratégica, a importância de que goza atualmente está na relevância histórica porque é reconhecida.\n(B) Ninguém teria porque negar a Paraty esse duplo merecimento de ser poesia e história, por que o tempo a escolheu para ser preservada e a natureza, para ser bela.\n(C) Os dissabores por que passa uma cidade turística devem ser prevenidos e evitados pela Casa Azul, porque ela nasceu para disciplinar o turismo.\n(D) Porque teria a cidade passado por tão longos anos de esquecimento? Criou-se uma estrada de ferro, eis porque.\n(E) Não há porquê imaginar que um esquecimento é sempre deplorável; veja-se como e por quê Paraty acabou se tornando um atraente centro turístico.","content_fingerprint":"esta correto o emprego de ambos os elementos sublinhados em a se o por que da importancia primitiva de paraty estava na sua localizacao estrategica a importancia de que goza atualmente esta na relevancia historica porque e reconhecida b ninguem teria porque negar a paraty esse duplo merecimento de ser poesia e historia por que o tempo a escolheu para ser preservada e a natureza para ser bela c os dissabores por que passa uma cidade turistica devem ser prevenidos e evitados pela casa azul porque ela nasceu para disciplinar o turismo d porque teria a cidade passado por tao longos anos de esquecimento criou se uma estrada de ferro eis porque e nao ha porque imaginar que um esquecimento e sempre deploravel veja se como e por que paraty acabou se tornando um atraente centro turistico","audit":{"id":"ed33482c-d143-55e1-8b4f-149b6316c522","document_sha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","document_name":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":4,"extracted_statement":"Está correto o emprego de ambos os elementos sublinhados em: a) Se o por quê da importância primitiva de Paraty estava na sua localização estratégica, a importância de que goza atualmente está na relevância histórica porque é reconhecida. b) Ninguém teria porque negar a Paraty esse duplo merecimento de ser poesia e história, por que o tempo a escolheu para ser preservada e a natureza, para ser bela. c) Os dissabores por que passa uma cidade turística devem ser prevenidos e evitados pela Casa Azul, porque ela nasceu para disciplinar o turismo. d) Porque teria a cidade passado por tão longos anos de esquecimento? Criou-se uma estrada de ferro, eis porque. e) Não há porquê imaginar que um esquecimento é sempre deplorável; veja-se como e por quê Paraty acabou se tornando um atraente centro turístico.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"9e8b1768-187c-5bec-97c7-ad12751c219c","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"9e8b1768-187c-5bec-97c7-ad12751c219c","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924:4","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Está correto o emprego de ambos os elementos sublinhados em:\n(A) Se o por quê da importância primitiva de Paraty estava na sua localização estratégica, a importância de que goza atualmente está na relevância histórica porque é reconhecida.\n(B) Ninguém teria porque negar a Paraty esse duplo merecimento de ser poesia e história, por que o tempo a escolheu para ser preservada e a natureza, para ser bela.\n(C) Os dissabores por que passa uma cidade turística devem ser prevenidos e evitados pela Casa Azul, porque ela nasceu para disciplinar o turismo.\n(D) Porque teria a cidade passado por tão longos anos de esquecimento? Criou-se uma estrada de ferro, eis porque.\n(E) Não há porquê imaginar que um esquecimento é sempre deplorável; veja-se como e por quê Paraty acabou se tornando um atraente centro turístico.","official_answer":"C","explanation":"Por que passa apresenta a preposição e o relativo, enquanto porque introduz a explicação da criação da entidade. Exemplo: dificuldades por que passa pode ser aproximado de dificuldades pelas quais passa. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-03_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"95a6527fc9ff1accc6dcfa86b037b6cea29a737bf99a0329ef863972c6733924","page":6,"itemNumber":4,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":18,"statement":"As palavras “superfície” (L. 2) e “saída” (L. 4) recebem acento gráfico, assim como são acentuadas graficamente todas as palavras a seguir: ideia, heroico, mantem, proximo e pe.","content_fingerprint":"as palavras superficie l 2 e saida l 4 recebem acento grafico assim como sao acentuadas graficamente todas as palavras a seguir ideia heroico mantem proximo e pe","audit":{"id":"91908ec3-995a-5922-8105-bca711e92b24","document_sha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","document_name":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":9,"item_number":1,"extracted_statement":"As palavras “superfície” (L. 2) e “saída” (L. 4) recebem acento gráfico, assim como são acentuadas graficamente todas as palavras a seguir: ideia, heroico, mantem, proximo e pe.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"f5923dac-cf63-567e-a352-2b133f98b00b","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"f5923dac-cf63-567e-a352-2b133f98b00b","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a:1","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"As palavras “superfície” (L. 2) e “saída” (L. 4) recebem acento gráfico, assim como são acentuadas graficamente todas as palavras a seguir: ideia, heroico, mantem, proximo e pe.","official_answer":"E","explanation":"Ideia e heroico são paroxítonas que não recebem o acento dos ditongos abertos depois do Acordo. Exemplo: herói mantém acento por ser oxítona, mas isso não autoriza escrever heróico. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","page":9,"itemNumber":1,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":19,"statement":"Nas alternativas a seguir, os acentos foram omitidos propositadamente. Assinale a alternativa em que todas as palavras deveriam ser graficamente acentuadas\n(A) rubrica, diluvio, viuva.\n(B) ambar, heroi, ilustra-lo.\n(C) protons, forceps, releem.\n(D) dificilmente, Piaui, misantropo.\n(E) perdoo, atribuimos, caiste.","content_fingerprint":"nas alternativas a seguir os acentos foram omitidos propositadamente assinale a alternativa em que todas as palavras deveriam ser graficamente acentuadas a rubrica diluvio viuva b ambar heroi ilustra lo c protons forceps releem d dificilmente piaui misantropo e perdoo atribuimos caiste","audit":{"id":"d43d7c0b-0aab-59bb-9db3-2889ccc9e9d7","document_sha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","document_name":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":9,"item_number":2,"extracted_statement":"Nas alternativas a seguir, os acentos foram omitidos propositadamente. Assinale a alternativa em que todas as palavras deveriam ser graficamente acentuadas a) rubrica, diluvio, viuva. b) ambar, heroi, ilustra-lo. c) protons, forceps, releem. d) dificilmente, Piaui, misantropo. e) perdoo, atribuimos, caiste.","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"e3fbe545-a07d-5750-b616-4360f15c8dbd","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e3fbe545-a07d-5750-b616-4360f15c8dbd","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a:2","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Nas alternativas a seguir, os acentos foram omitidos propositadamente. Assinale a alternativa em que todas as palavras deveriam ser graficamente acentuadas\n(A) rubrica, diluvio, viuva.\n(B) ambar, heroi, ilustra-lo.\n(C) protons, forceps, releem.\n(D) dificilmente, Piaui, misantropo.\n(E) perdoo, atribuimos, caiste.","official_answer":"B","explanation":"Âmbar, herói e ilustrá-lo exigem os sinais nas construções apresentadas. Exemplo: o infinitivo ligado ao pronome perde o r e preserva a indicação da tonicidade em ilustrá-lo; rubrica não recebe acento. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","page":9,"itemNumber":2,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":20,"statement":"Observe as frases abaixo e responda a seguir. (1) Fiz toda a janta usando só o ________ . (2) Na ________ , os homens viviam em cavernas. (3) Meu ________ é ________ . As palavras que completam corretamente as lacunas em (1), (2) e (3) são, respectivamente:\n(A) micro-ondas / pré-história / microcomputador / seminovo.\n(B) microondas / préhistória / microcomputador / seminovo.\n(C) micro-ondas / pré-história /microcomputador / semi-novo.\n(D) microndas / preistoria / microcomputador / seminovo.\n(E) micro-ondas / pré-história / micro-computador / seminovo.","content_fingerprint":"observe as frases abaixo e responda a seguir 1 fiz toda a janta usando so o 2 na os homens viviam em cavernas 3 meu e as palavras que completam corretamente as lacunas em 1 2 e 3 sao respectivamente a micro ondas pre historia microcomputador seminovo b microondas prehistoria microcomputador seminovo c micro ondas pre historia microcomputador semi novo d microndas preistoria microcomputador seminovo e micro ondas pre historia micro computador seminovo","audit":{"id":"064b9a1e-7cd3-5e85-bcf3-0e1c3a0d6631","document_sha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","document_name":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":10,"item_number":3,"extracted_statement":"Observe as frases abaixo e responda a seguir. (1) Fiz toda a janta usando só o ________ . (2) Na ________ , os homens viviam em cavernas. (3) Meu ________ é ________ . As palavras que completam corretamente as lacunas em (1), (2) e (3) são, respectivamente: a) micro-ondas / pré-história / microcomputador / seminovo. b) microondas / préhistória / microcomputador / seminovo. c) micro-ondas / pré-história /microcomputador / semi-novo. d) microndas / preistoria / microcomputador / seminovo. e) micro-ondas / pré-história / micro-computador / seminovo.","provided_answer":"A","current_answer":"A","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"ca6b9453-9507-5d2b-86b2-7f6eab6556b3","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"ca6b9453-9507-5d2b-86b2-7f6eab6556b3","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a:3","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Observe as frases abaixo e responda a seguir. (1) Fiz toda a janta usando só o ________ . (2) Na ________ , os homens viviam em cavernas. (3) Meu ________ é ________ . As palavras que completam corretamente as lacunas em (1), (2) e (3) são, respectivamente:\n(A) micro-ondas / pré-história / microcomputador / seminovo.\n(B) microondas / préhistória / microcomputador / seminovo.\n(C) micro-ondas / pré-história /microcomputador / semi-novo.\n(D) microndas / preistoria / microcomputador / seminovo.\n(E) micro-ondas / pré-história / micro-computador / seminovo.","official_answer":"A","explanation":"As formas de referência são micro-ondas, pré-história, microcomputador e seminovo. Exemplo: a vogal repetida em micro-ondas não permite transferir o hífen a seminovo, cuja formação é diferente. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","page":10,"itemNumber":3,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":21,"statement":"Assinale a alternativa correta, segundo o novo acordo ortográfico: “O pronunciamento do parlamentar na _______ da peça de teatro teve repercussão na impressa, de modo que o outro deputado, ao desembarcar do seu ____ rumo à cidade de ______, no estado do ________também falou sobre o assunto: Os que _______ jornais saberão do que estou falando”.\n(A) Estréia – vôo – Parnaíba – Piauí – lêem\n(B) Estreia – vôo – Parnaiba – Piaui – lêem\n(C) Estreia – voo – Parnaíba – Piaui – leem\n(D) Estreia – voo – Parnaíba – Piauí – leem\n(E) Estreia – voo – Parnaíba – Piauí – lêem","content_fingerprint":"assinale a alternativa correta segundo o novo acordo ortografico o pronunciamento do parlamentar na da peca de teatro teve repercussao na impressa de modo que o outro deputado ao desembarcar do seu rumo a cidade de no estado do tambem falou sobre o assunto os que jornais saberao do que estou falando a estreia voo parnaiba piaui leem b estreia voo parnaiba piaui leem c estreia voo parnaiba piaui leem d estreia voo parnaiba piaui leem e estreia voo parnaiba piaui leem","audit":{"id":"bbb417d9-847e-59c1-831d-472dc29f2458","document_sha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","document_name":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":10,"item_number":4,"extracted_statement":"Assinale a alternativa correta, segundo o novo acordo ortográfico: “O pronunciamento do parlamentar na _______ da peça de teatro teve repercussão na impressa, de modo que o outro deputado, ao desembarcar do seu ____ rumo à cidade de ______, no estado do ________também falou sobre o assunto: Os que _______ jornais saberão do que estou falando”. a) Estréia – vôo – Parnaíba – Piauí – lêem b) Estreia – vôo – Parnaiba – Piaui – lêem c) Estreia – voo – Parnaíba – Piaui – leem d) Estreia – voo – Parnaíba – Piauí – leem e) Estreia – voo – Parnaíba – Piauí – lêem","provided_answer":"D","current_answer":"D","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"171b4c9f-3f6a-5087-8188-b86a948805b6","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"171b4c9f-3f6a-5087-8188-b86a948805b6","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a:4","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"Assinale a alternativa correta, segundo o novo acordo ortográfico: “O pronunciamento do parlamentar na _______ da peça de teatro teve repercussão na impressa, de modo que o outro deputado, ao desembarcar do seu ____ rumo à cidade de ______, no estado do ________também falou sobre o assunto: Os que _______ jornais saberão do que estou falando”.\n(A) Estréia – vôo – Parnaíba – Piauí – lêem\n(B) Estreia – vôo – Parnaiba – Piaui – lêem\n(C) Estreia – voo – Parnaíba – Piaui – leem\n(D) Estreia – voo – Parnaíba – Piauí – leem\n(E) Estreia – voo – Parnaíba – Piauí – lêem","official_answer":"D","explanation":"Estreia e voo perderam os sinais antigos; Parnaíba e Piauí conservam os acentos pertinentes; leem não tem circunflexo. Exemplo: a atualização de uma regra não elimina a acentuação de todos os hiatos. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-04_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"8f94cef1afd5c90de1e6147df865f8f61e15aefa43ca35a29db90542efd3871a","page":10,"itemNumber":4,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":22,"statement":"A troca de posição de elementos que provoca perda de coerência ou incorreção gramatical é:\n(A) talvez o automóvel não seja descartável tão facilmente / talvez o automóvel não seja tão facilmente descartável;\n(B) este jornal, em uma série de reportagens, nestes dias, mostrou / Nestes dias, em uma série de reportagens, este jornal mostrou;\n(C) mostrou o privilégio que os governos dão ao uso do carro / mostrou que os governos dão privilégio ao uso do carro;\n(D) surpreendentemente, houve entrevistado que opinou favoravelmente / Houve entrevistado que opinou favorável e surpreendentemente;\n(E) cidade rodoviária e dispersa / cidade dispersa e rodoviária.","content_fingerprint":"a troca de posicao de elementos que provoca perda de coerencia ou incorrecao gramatical e a talvez o automovel nao seja descartavel tao facilmente talvez o automovel nao seja tao facilmente descartavel b este jornal em uma serie de reportagens nestes dias mostrou nestes dias em uma serie de reportagens este jornal mostrou c mostrou o privilegio que os governos dao ao uso do carro mostrou que os governos dao privilegio ao uso do carro d surpreendentemente houve entrevistado que opinou favoravelmente houve entrevistado que opinou favoravel e surpreendentemente e cidade rodoviaria e dispersa cidade dispersa e rodoviaria","audit":{"id":"9758b351-bdba-54d2-9d4d-fde627527154","document_sha256":"d52cf40569db37ee02d2dbd3d49d321cfe3127cf8d23f7c908d49ec11159b698","document_name":"02-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":1,"extracted_statement":"A troca de posição de elementos que provoca perda de coerência ou incorreção gramatical é: a) talvez o automóvel não seja descartável tão facilmente / talvez o automóvel não seja tão facilmente descartável; b) este jornal, em uma série de reportagens, nestes dias, mostrou / Nestes dias, em uma série de reportagens, este jornal mostrou; c) mostrou o privilégio que os governos dão ao uso do carro / mostrou que os governos dão privilégio ao uso do carro; d) surpreendentemente, houve entrevistado que opinou favoravelmente / Houve entrevistado que opinou favorável e surpreendentemente; e) cidade rodoviária e dispersa / cidade dispersa e rodoviária.","provided_answer":"D","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":23,"statement":"No seguinte período, a palavra em destaque está grafada de acordo com a ortografia oficial:\n(A) O sindicato se preocupa com o aspécto educativo da cartilha.\n(B) Várias entidades mantêm convênio conosco.\n(C) O consumidor tem de ser consciênte de seu papel de cidadão.\n(D) O substântivo que traduz essa cartilha é “seriedade”.\n(E) No rítmo em que a sociedade caminha, em breve exerceremos plena cidadania.","content_fingerprint":"no seguinte periodo a palavra em destaque esta grafada de acordo com a ortografia oficial a o sindicato se preocupa com o aspecto educativo da cartilha b varias entidades mantem convenio conosco c o consumidor tem de ser consciente de seu papel de cidadao d o substantivo que traduz essa cartilha e seriedade e no ritmo em que a sociedade caminha em breve exerceremos plena cidadania","audit":{"id":"8abc8167-efa4-55b0-a9f5-9b31f6f08769","document_sha256":"1246899ce140d6a73b6cabd371a5a5c396d552262b453a3f5c7841568e6f1f46","document_name":"02-05_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":1,"extracted_statement":"No seguinte período, a palavra em destaque está grafada de acordo com a ortografia oficial: a) O sindicato se preocupa com o aspécto educativo da cartilha. b) Várias entidades mantêm convênio conosco. c) O consumidor tem de ser consciênte de seu papel de cidadão. d) O substântivo que traduz essa cartilha é “seriedade”. e) No rítmo em que a sociedade caminha, em breve exerceremos plena cidadania.","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"e6e8697c-7b13-55da-ad78-119afcdb8069","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"e6e8697c-7b13-55da-ad78-119afcdb8069","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:1246899ce140d6a73b6cabd371a5a5c396d552262b453a3f5c7841568e6f1f46:1","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"No seguinte período, a palavra em destaque está grafada de acordo com a ortografia oficial:\n(A) O sindicato se preocupa com o aspécto educativo da cartilha.\n(B) Várias entidades mantêm convênio conosco.\n(C) O consumidor tem de ser consciênte de seu papel de cidadão.\n(D) O substântivo que traduz essa cartilha é “seriedade”.\n(E) No rítmo em que a sociedade caminha, em breve exerceremos plena cidadania.","official_answer":"B","explanation":"Mantêm é a forma plural adequada no contexto várias entidades. Exemplo: entidade mantém contrasta com entidades mantêm; aspecto, consciente, substantivo e ritmo não recebem os sinais das outras opções. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-05_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"1246899ce140d6a73b6cabd371a5a5c396d552262b453a3f5c7841568e6f1f46","page":6,"itemNumber":1,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":24,"statement":"No texto abaixo, apenas uma palavra, dentre as destacadas, está grafada corretamente e de acordo com a norma-padrão. Um fotógrafo sulafricano apresentou uma bela expozição com doze imagens de pássaro em voo entorno de uma antena disfarçada. Quem não pôde ver o trabalho do fotógrafo vai têr outra oportunidade em breve. A palavra nessas condições é\n(A) sulafricano\n(B) expozição\n(C) entorno\n(D) pôde\n(E) têr","content_fingerprint":"no texto abaixo apenas uma palavra dentre as destacadas esta grafada corretamente e de acordo com a norma padrao um fotografo sulafricano apresentou uma bela expozicao com doze imagens de passaro em voo entorno de uma antena disfarcada quem nao pode ver o trabalho do fotografo vai ter outra oportunidade em breve a palavra nessas condicoes e a sulafricano b expozicao c entorno d pode e ter","audit":{"id":"ec704df2-a673-5eff-9b0b-691831682bb2","document_sha256":"1246899ce140d6a73b6cabd371a5a5c396d552262b453a3f5c7841568e6f1f46","document_name":"02-05_lingua_portuguesa_giancarla_bombonato.pdf","source_page":6,"item_number":2,"extracted_statement":"No texto abaixo, apenas uma palavra, dentre as destacadas, está grafada corretamente e de acordo com a norma-padrão. Um fotógrafo sulafricano apresentou uma bela expozição com doze imagens de pássaro em voo entorno de uma antena disfarçada. Quem não pôde ver o trabalho do fotógrafo vai têr outra oportunidade em breve. A palavra nessas condições é a) sulafricano b) expozição c) entorno d) pôde e) têr","provided_answer":"D","current_answer":"D","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"108f8769-ed71-597c-8f21-e99e245f8cd8","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"108f8769-ed71-597c-8f21-e99e245f8cd8","source_id":"4dbac33a-284d-57c0-bfa7-2788ce6fd887","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","external_item_key":"didactic:1246899ce140d6a73b6cabd371a5a5c396d552262b453a3f5c7841568e6f1f46:2","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Ortografia e acentuação","tested_topic":"Ortografia e acentuação","question_text":"No texto abaixo, apenas uma palavra, dentre as destacadas, está grafada corretamente e de acordo com a norma-padrão. Um fotógrafo sulafricano apresentou uma bela expozição com doze imagens de pássaro em voo entorno de uma antena disfarçada. Quem não pôde ver o trabalho do fotógrafo vai têr outra oportunidade em breve. A palavra nessas condições é\n(A) sulafricano\n(B) expozição\n(C) entorno\n(D) pôde\n(E) têr","official_answer":"D","explanation":"Pôde é grafia correta e distingue o passado de pode no presente. Exemplo: ontem não pôde comparecer não leva o mesmo tempo de hoje não pode comparecer; expozição e têr não são as grafias propostas pela norma atual. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Decreto 6.583/2008 — Acordo Ortográfico da Língua Portuguesa","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/decreto/d6583.htm","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:44:55.441492+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"02-05_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Ortografia e acentuação","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"1246899ce140d6a73b6cabd371a5a5c396d552262b453a3f5c7841568e6f1f46","page":6,"itemNumber":2,"materialSlug":"portugues-ortografia-acentuacao-atual","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":25,"statement":"O segmento do texto em que o vocábulo “mais” pertence a uma classe diferente das demais é\n(A) “A questão acerca da aposentadoria das mulheres em condições mais benéficas...”.\n(B) “um dos maiores e mais antigos bancos do Brasil”.\n(C) “Filhos estudam por mais tempo”.\n(D) “recebem salários mais baixos”.\n(E) “uma aposentadoria em idade mais jovem”.","content_fingerprint":"o segmento do texto em que o vocabulo mais pertence a uma classe diferente das demais e a a questao acerca da aposentadoria das mulheres em condicoes mais beneficas b um dos maiores e mais antigos bancos do brasil c filhos estudam por mais tempo d recebem salarios mais baixos e uma aposentadoria em idade mais jovem","audit":{"id":"6f635b2b-8ea7-50fb-88e0-585d509a6507","document_sha256":"46ccd313583044155a758bb37cc2eacbd277a178b8fa61c3aa2295ef3a13dae1","document_name":"03-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":3,"item_number":1,"extracted_statement":"O segmento do texto em que o vocábulo “mais” pertence a uma classe diferente das demais é a) “A questão acerca da aposentadoria das mulheres em condições mais benéficas...”. b) “um dos maiores e mais antigos bancos do Brasil”. c) “Filhos estudam por mais tempo”. d) “recebem salários mais baixos”. e) “uma aposentadoria em idade mais jovem”.","provided_answer":"C","current_answer":"C","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"11011ffc-9fb1-51fe-9917-5611e563d848","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"11011ffc-9fb1-51fe-9917-5611e563d848","source_id":"8839c291-1d0d-554e-b02a-72a35ac278b4","syllabus_topic_id":"5873244d-48e6-4241-a474-b5db3317d27f","external_item_key":"didactic:46ccd313583044155a758bb37cc2eacbd277a178b8fa61c3aa2295ef3a13dae1:1","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Classes de palavras","tested_topic":"Classes de palavras","question_text":"O segmento do texto em que o vocábulo “mais” pertence a uma classe diferente das demais é\n(A) “A questão acerca da aposentadoria das mulheres em condições mais benéficas...”.\n(B) “um dos maiores e mais antigos bancos do Brasil”.\n(C) “Filhos estudam por mais tempo”.\n(D) “recebem salários mais baixos”.\n(E) “uma aposentadoria em idade mais jovem”.","official_answer":"C","explanation":"Em mais tempo, mais acompanha o substantivo e tem valor quantificador. Nas outras construções selecionadas intensifica adjetivos. Exemplo: mais jovem modifica jovem, não a duração de um intervalo. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T03:07:02.833711+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"03-02_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Classes de palavras","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"46ccd313583044155a758bb37cc2eacbd277a178b8fa61c3aa2295ef3a13dae1","page":3,"itemNumber":1,"materialSlug":"portugues-classes-palavras-contexto","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":26,"statement":"O par de frases em que as palavras destacadas possuem a mesma classe gramatical é:\n(A) “em disfarçar antenas de telecomunicações pelo mundo afora” (l46-47) – O pelo daquele cachorro está brilhando.\n(B) “Os custos são elevados:” (l 50-51) – Os elevados são vias de passagem necessárias às grandes cidades.\n(C) “A Verizon se deu ao trabalho de construir” (l56) – Eu trabalho sempre de manhã e à tarde.\n(D) “no maior capricho e, volta e meia,” (l 62) – É necessário dar uma volta na praça para chegar à rua principal.\n(E) “desavisados deixam jornais e revistas na porta.” (#2;. 63-64) – As provas foram revistas por especialistas.","content_fingerprint":"o par de frases em que as palavras destacadas possuem a mesma classe gramatical e a em disfarcar antenas de telecomunicacoes pelo mundo afora l46 47 o pelo daquele cachorro esta brilhando b os custos sao elevados l 50 51 os elevados sao vias de passagem necessarias as grandes cidades c a verizon se deu ao trabalho de construir l56 eu trabalho sempre de manha e a tarde d no maior capricho e volta e meia l 62 e necessario dar uma volta na praca para chegar a rua principal e desavisados deixam jornais e revistas na porta 2 63 64 as provas foram revistas por especialistas","audit":{"id":"fcc08441-9cee-54f7-b9e4-5f3b946a490b","document_sha256":"46ccd313583044155a758bb37cc2eacbd277a178b8fa61c3aa2295ef3a13dae1","document_name":"03-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":3,"item_number":2,"extracted_statement":"O par de frases em que as palavras destacadas possuem a mesma classe gramatical é: a) “em disfarçar antenas de telecomunicações pelo mundo afora” (l46-47) – O pelo daquele cachorro está brilhando. b) “Os custos são elevados:” (l 50-51) – Os elevados são vias de passagem necessárias às grandes cidades. c) “A Verizon se deu ao trabalho de construir” (l56) – Eu trabalho sempre de manhã e à tarde. d) “no maior capricho e, volta e meia,” (l 62) – É necessário dar uma volta na praça para chegar à rua principal. e) “desavisados deixam jornais e revistas na porta.” (#2;. 63-64) – As provas foram revistas por especialistas.","provided_answer":"D","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":27,"statement":"Na passagem do terceiro parágrafo – ... veio enriquecer nosso canteirinho vulgar... –, o substantivo, empregado no diminutivo, contribui para expressar a ideia de\n(A) exatidão.\n(B) desprezo.\n(C) simplicidade.\n(D) soberba.\n(E) abundância.","content_fingerprint":"na passagem do terceiro paragrafo veio enriquecer nosso canteirinho vulgar o substantivo empregado no diminutivo contribui para expressar a ideia de a exatidao b desprezo c simplicidade d soberba e abundancia","audit":{"id":"e19cc342-a06d-5274-b14d-553e011f