0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"aa7e0ab7-9ebb-5fca-87eb-04dc4b81aa63","source_id":"421bb930-7b5a-5f24-9597-651fbf2ba62e","syllabus_topic_id":"5873244d-48e6-4241-a474-b5db3317d27f","external_item_key":"didactic:7c664993ced09a3f01d7034ed40ff76ce505065c0545d389eca6a2149101faea:1","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Concordância verbal e nominal","tested_topic":"Concordância verbal e nominal","question_text":"Na frase “Todos queremos viver em liberdade”, o exemplo de concordância verbal em “Todos queremos” se repete na seguinte frase:\n(A) Não são criativos todos os brasileiros.\n(B) Os candidatos estamos preocupados com a prova.\n(C) V. Exª. parece entristecido.\n(D) Todos nós desejamos a liberdade.\n(E) A gente não deseja mais viver.","official_answer":"B","explanation":"Os candidatos estamos inclui o falante no conjunto referido e reproduz concordância ideológica de pessoa. Exemplo: todos nós desejamos explicita nós e não apresenta o mesmo descompasso formal da construção inicial. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Senado Federal — concordância verbal","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/concordancia-verbal","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:47:55.585610+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"11-05_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Concordância verbal e nominal","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"7c664993ced09a3f01d7034ed40ff76ce505065c0545d389eca6a2149101faea","page":4,"itemNumber":1,"materialSlug":"portugues-concordancia-verbal-nominal","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":125,"statement":"Assinale a alternativa que apresenta um erro de concordância verbal.\n(A) Arrombou-se, pela manhã, a casa da vizinha.\n(B) Precisam-se de pedreiros para esta obra terminar no tempo certo.\n(C) Alugam-se casa e apartamentos de veraneio para temporada.\n(D) Necessita-se de novos funcionários.\n(E) Espalharam-se, durante o vendaval, todas as folhas pelo quintal.","content_fingerprint":"assinale a alternativa que apresenta um erro de concordancia verbal a arrombou se pela manha a casa da vizinha b precisam se de pedreiros para esta obra terminar no tempo certo c alugam se casa e apartamentos de veraneio para temporada d necessita se de novos funcionarios e espalharam se durante o vendaval todas as folhas pelo quintal","audit":{"id":"e6f1add2-2952-52ce-a991-e3b5ea9c0c1d","document_sha256":"7c664993ced09a3f01d7034ed40ff76ce505065c0545d389eca6a2149101faea","document_name":"11-05_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":2,"extracted_statement":"Assinale a alternativa que apresenta um erro de concordância verbal. a) Arrombou-se, pela manhã, a casa da vizinha. b) Precisam-se de pedreiros para esta obra terminar no tempo certo. c) Alugam-se casa e apartamentos de veraneio para temporada. d) Necessita-se de novos funcionários. e) Espalharam-se, durante o vendaval, todas as folhas pelo quintal.","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"25824be4-7637-52e1-8677-4f6615a36f2d","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"25824be4-7637-52e1-8677-4f6615a36f2d","source_id":"421bb930-7b5a-5f24-9597-651fbf2ba62e","syllabus_topic_id":"5873244d-48e6-4241-a474-b5db3317d27f","external_item_key":"didactic:7c664993ced09a3f01d7034ed40ff76ce505065c0545d389eca6a2149101faea:2","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Concordância verbal e nominal","tested_topic":"Concordância verbal e nominal","question_text":"Assinale a alternativa que apresenta um erro de concordância verbal.\n(A) Arrombou-se, pela manhã, a casa da vizinha.\n(B) Precisam-se de pedreiros para esta obra terminar no tempo certo.\n(C) Alugam-se casa e apartamentos de veraneio para temporada.\n(D) Necessita-se de novos funcionários.\n(E) Espalharam-se, durante o vendaval, todas as folhas pelo quintal.","official_answer":"B","explanation":"Precisa-se de pedreiros exige verbo singular na construção de indeterminação. Exemplo: alugam-se casas tem sujeito paciente e pode ir ao plural; os dois usos do se não são equivalentes. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Senado Federal — concordância verbal","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/concordancia-verbal","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:47:55.585610+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"11-05_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Concordância verbal e nominal","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"7c664993ced09a3f01d7034ed40ff76ce505065c0545d389eca6a2149101faea","page":4,"itemNumber":2,"materialSlug":"portugues-concordancia-verbal-nominal","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":126,"statement":"Leia o texto. Mesmo estando apta_________ desenvolver atividades na área de ensino, a maioria dos profissionais que conclui o ensino superior sente-se impelida __________ buscar outras áreas _______ que possa trabalhar, geralmente atraída _____ salários mais expressivos e melhores condições de trabalho. Considerando-se as regras de regência, verbal e nominal, de acordo com a norma-padrão da língua portuguesa, as lacunas do texto devem ser preenchidas, correta e respectivamente, com:\n(A) a … de … de … por\n(B) a … a … em … por\n(C) em … por … a … de\n(D) a … com … por … com\n(E) por … a … em … com","content_fingerprint":"leia o texto mesmo estando apta desenvolver atividades na area de ensino a maioria dos profissionais que conclui o ensino superior sente se impelida buscar outras areas que possa trabalhar geralmente atraida salarios mais expressivos e melhores condicoes de trabalho considerando se as regras de regencia verbal e nominal de acordo com a norma padrao da lingua portuguesa as lacunas do texto devem ser preenchidas correta e respectivamente com a a de de por b a a em por c em por a de d a com por com e por a em com","audit":{"id":"a9263114-82dd-5ca9-9e22-e6b5982efcee","document_sha256":"0c32b951d0aefedd29a7302bf3312225c2af62c92ec0d8ab7e1e84c3da4a3752","document_name":"12-01_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":1,"extracted_statement":"Leia o texto. Mesmo estando apta_________ desenvolver atividades na área de ensino, a maioria dos profissionais que conclui o ensino superior sente-se impelida __________ buscar outras áreas _______ que possa trabalhar, geralmente atraída _____ salários mais expressivos e melhores condições de trabalho. Considerando-se as regras de regência, verbal e nominal, de acordo com a norma-padrão da língua portuguesa, as lacunas do texto devem ser preenchidas, correta e respectivamente, com: a) a … de … de … por b) a … a … em … por c) em … por … a … de d) a … com … por … com e) por … a … em … com","provided_answer":"B","current_answer":"B","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"5521e0b3-4c4d-5c5f-8153-3481ec2b6526","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"5521e0b3-4c4d-5c5f-8153-3481ec2b6526","source_id":"1e2fd682-059c-5a08-b8ed-416cc61441fc","syllabus_topic_id":"5873244d-48e6-4241-a474-b5db3317d27f","external_item_key":"didactic:0c32b951d0aefedd29a7302bf3312225c2af62c92ec0d8ab7e1e84c3da4a3752:1","contest_name":"Material didático — Língua Portuguesa","contest_year":2026,"career_name":"Agente de Polícia Federal","exam_board":"Material didático","subject":"Língua Portuguesa","subtopic":"Regência verbal, nominal e crase","tested_topic":"Regência verbal, nominal e crase","question_text":"Leia o texto. Mesmo estando apta_________ desenvolver atividades na área de ensino, a maioria dos profissionais que conclui o ensino superior sente-se impelida __________ buscar outras áreas _______ que possa trabalhar, geralmente atraída _____ salários mais expressivos e melhores condições de trabalho. Considerando-se as regras de regência, verbal e nominal, de acordo com a norma-padrão da língua portuguesa, as lacunas do texto devem ser preenchidas, correta e respectivamente, com:\n(A) a … de … de … por\n(B) a … a … em … por\n(C) em … por … a … de\n(D) a … com … por … com\n(E) por … a … em … com","official_answer":"B","explanation":"As relações são apta a, impelida a, áreas em que e atraída por. Exemplo: a escolha de em que preserva a ligação locativa de trabalhar nas áreas mencionadas. Origem: exercício de material didático, com adaptação e revisão linguística; não certificado como item oficial de banca. Referências institucionais de ortografia e uso formal não significam transcrição literal desta análise.","legal_basis":[{"title":"Senado Federal — crase","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/crase","escopo":"Referência institucional de ortografia/uso formal; análise didática própria do enunciado."}],"difficulty":"média","content_status":"active","is_original":false,"verified_at":"2026-10-25T03:23:26.419620+00:00","law_version_checked_at":"2026-10-25T02:47:56.606572+00:00","didactic_provenance":{"origin":"didactic_material","documentName":"12-01_lingua_portuguesa_giancarla_bombonato.pdf","documentTitle":"Regência verbal, nominal e crase","publisher":"AlfaCon — material didático fornecido pelo usuário","documentSha256":"0c32b951d0aefedd29a7302bf3312225c2af62c92ec0d8ab7e1e84c3da4a3752","page":4,"itemNumber":1,"materialSlug":"portugues-regencia-crase","reviewedAt":"2026-10-25T03:23:26.419620+00:00","adapted":true}}},{"input_index":127,"statement":"Estamos no trânsito de São Paulo, ano 2030. E não é preciso apertar os cintos: nosso carro agora trafega sozinho pelas ruas, salvo de acidentes, graças a um sistema que o mantém em sincronia com os demais veículos lá fora. O volante, item de uso opcional, inclina-se de um lado para outro como se fosse manuseado por um fantasma. Mas ninguém liga pra ele – até porque o carro do futuro está cheio de novidades bem mais legais. Em vez dos tradicionais quatro assentos, o que temos agora é uma verdadeira sala de estar, com poltronas reclináveis, mesa no centro e telas de LED. As velhas carrocerias de aço foram substituídas por redomas translúcidas, com visibilidade total para o ambiente externo. Se você preferir, é possível torná-la opaca e transformar o carro em um ambiente privado, quase como um quarto ambulante. Como o sistema de navegação é autônomo, basta informar ao computador aonde você quer ir e ele faz o resto. Resta passar o tempo da forma que lhe der na telha: lendo, trabalhando, assistindo ao seu seriado preferido ou até dormindo. A viagem é agradável e silenciosa. (Superinteressante, novembro de 2014). O segmento do texto em que a preposição destacada faz parte de um adjunto e NÃO é solicitada obrigatoriamente por nenhum termo anterior é:\n(A) “Estamos no trânsito de São Paulo”;\n(B) “salvo de acidentes”;\n(C) “em sincronia com os demais veículos lá fora”;\n(D) “assistindo ao seu seriado preferido”;\n(E) “basta informar ao computador”.","content_fingerprint":"estamos no transito de sao paulo ano 2030 e nao e preciso apertar os cintos nosso carro agora trafega sozinho pelas ruas salvo de acidentes gracas a um sistema que o mantem em sincronia com os demais veiculos la fora o volante item de uso opcional inclina se de um lado para outro como se fosse manuseado por um fantasma mas ninguem liga pra ele ate porque o carro do futuro esta cheio de novidades bem mais legais em vez dos tradicionais quatro assentos o que temos agora e uma verdadeira sala de estar com poltronas reclinaveis mesa no centro e telas de led as velhas carrocerias de aco foram substituidas por redomas translucidas com visibilidade total para o ambiente externo se voce preferir e possivel torna la opaca e transformar o carro em um ambiente privado quase como um quarto ambulante como o sistema de navegacao e autonomo basta informar ao computador aonde voce quer ir e ele faz o resto resta passar o tempo da forma que lhe der na telha lendo trabalhando assistindo ao seu seriado preferido ou ate dormindo a viagem e agradavel e silenciosa superinteressante novembro de 2014 o segmento do texto em que a preposicao destacada faz parte de um adjunto e nao e solicitada obrigatoriamente por nenhum termo anterior e a estamos no transito de sao paulo b salvo de acidentes c em sincronia com os demais veiculos la fora d assistindo ao seu seriado preferido e basta informar ao computador","audit":{"id":"5ac4b8eb-4a24-58a6-84e8-fff4444cb382","document_sha256":"0c32b951d0aefedd29a7302bf3312225c2af62c92ec0d8ab7e1e84c3da4a3752","document_name":"12-01_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":2,"extracted_statement":"Estamos no trânsito de São Paulo, ano 2030. E não é preciso apertar os cintos: nosso carro agora trafega sozinho pelas ruas, salvo de acidentes, graças a um sistema que o mantém em sincronia com os demais veículos lá fora. O volante, item de uso opcional, inclina-se de um lado para outro como se fosse manuseado por um fantasma. Mas ninguém liga pra ele – até porque o carro do futuro está cheio de novidades bem mais legais. Em vez dos tradicionais quatro assentos, o que temos agora é uma verdadeira sala de estar, com poltronas reclináveis, mesa no centro e telas de LED. As velhas carrocerias de aço foram substituídas por redomas translúcidas, com visibilidade total para o ambiente externo. Se você preferir, é possível torná-la opaca e transformar o carro em um ambiente privado, quase como um quarto ambulante. Como o sistema de navegação é autônomo, basta informar ao computador aonde você quer ir e ele faz o resto. Resta passar o tempo da forma que lhe der na telha: lendo, trabalhando, assistindo ao seu seriado preferido ou até dormindo. A viagem é agradável e silenciosa. (Superinteressante, novembro de 2014). O segmento do texto em que a preposição destacada faz parte de um adjunto e NÃO é solicitada obrigatoriamente por nenhum termo anterior é: a) “Estamos no trânsito de São Paulo”; b) “salvo de acidentes”; c) “em sincronia com os demais veículos lá fora”; d) “assistindo ao seu seriado preferido”; e) “basta informar ao computador”.","provided_answer":"A","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":128,"statement":"Empregou-se corretamente a regência verbal em:\n(A) As crianças gostam que lhes ajudemos.\n(B) O tio do garoto pagou o dentista.\n(C) A mãe perdoou o assassino do filho.\n(D) O homem digno prefere um inimigo declarado do que um falso amigo.\n(E) Todos os candidatos visam à aprovação no concurso.","content_fingerprint":"empregou se corretamente a regencia verbal em a as criancas gostam que lhes ajudemos b o tio do garoto pagou o dentista c a mae perdoou o assassino do filho d o homem digno prefere um inimigo declarado do que um falso amigo e todos os candidatos visam a aprovacao no concurso","audit":{"id":"1ea381b6-b57f-5315-9487-1c562d14bddb","document_sha256":"3e8198c4d0cda3487219301eef31455de1318fc0872415e892d9800e7084feba","document_name":"12-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":7,"item_number":1,"extracted_statement":"Empregou-se corretamente a regência verbal em: a) As crianças gostam que lhes ajudemos. b) O tio do garoto pagou o dentista. c) A mãe perdoou o assassino do filho. d) O homem digno prefere um inimigo declarado do que um falso amigo. e) Todos os candidatos visam à aprovação no concurso.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":129,"statement":"Emprega-se corretamente a regência verbal em:\n(A) As pessoas preferem expor suas vidas aos demais passageiros do ônibus do que revelar uma boa educação.\n(B) A atitude de proibir a audição de música no celular sem fone de ouvidos visava ao conforto dos passageiros.\n(C) Aqueles que ouvem, no ônibus, as músicas em alto som, não respeitam aos princípios da boa educação.\n(D) Todos, nos ônibus, observam ao desrespeito dos que expõem detalhes de suas vidas aos passageiros vizinhos.\n(E) Os passageiros do ônibus não tinham como escapar ao alto barulho do som das falas dos pouco discretos.","content_fingerprint":"emprega se corretamente a regencia verbal em a as pessoas preferem expor suas vidas aos demais passageiros do onibus do que revelar uma boa educacao b a atitude de proibir a audicao de musica no celular sem fone de ouvidos visava ao conforto dos passageiros c aqueles que ouvem no onibus as musicas em alto som nao respeitam aos principios da boa educacao d todos nos onibus observam ao desrespeito dos que expoem detalhes de suas vidas aos passageiros vizinhos e os passageiros do onibus nao tinham como escapar ao alto barulho do som das falas dos pouco discretos","audit":{"id":"6e1fea4c-0218-56b6-85b6-6f8c3152ddaa","document_sha256":"3e8198c4d0cda3487219301eef31455de1318fc0872415e892d9800e7084feba","document_name":"12-02_lingua_portuguesa_giancarla_bombonato.pdf","source_page":7,"item_number":2,"extracted_statement":"Emprega-se corretamente a regência verbal em: a) As pessoas preferem expor suas vidas aos demais passageiros do ônibus do que revelar uma boa educação. b) A atitude de proibir a audição de música no celular sem fone de ouvidos visava ao conforto dos passageiros. c) Aqueles que ouvem, no ônibus, as músicas em alto som, não respeitam aos princípios da boa educação. d) Todos, nos ônibus, observam ao desrespeito dos que expõem detalhes de suas vidas aos passageiros vizinhos. e) Os passageiros do ônibus não tinham como escapar ao alto barulho do som das falas dos pouco discretos.","provided_answer":"B","current_answer":null,"review_status":"needs_review","review_note":"Exige revisão individual da extração, destaques, texto-base, alternativas e gabarito; resposta da apostila não certifica atualização.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":130,"statement":"Tudo o que eu aprendo está sujeito à imediata erosão. O uso do sinal indicativo de crase em ‘à imediata erosão’ é obrigatório.","content_fingerprint":"tudo o que eu aprendo esta sujeito a imediata erosao o uso do sinal indicativo de crase em a imediata erosao e obrigatorio","audit":{"id":"b841c753-6401-5af4-bbce-7344e88feb2b","document_sha256":"ab4c99104c3359eb63ac78984c24d75be4e967a7f75e5b46f855efbdb1078a88","document_name":"12-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":1,"extracted_statement":"Tudo o que eu aprendo está sujeito à imediata erosão. O uso do sinal indicativo de crase em ‘à imediata erosão’ é obrigatório.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"O gabarito de crase ou o recorte extraído exige conciliação; não aceitar automaticamente a chave antiga sem o trecho e condições completos.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":131,"statement":"Observe o trecho: O emprego do sinal indicativo de crase em “às necessidades” (L.12) é obrigatório; a omissão desse sinal provocaria erro gramatical por desrespeitar as regras de regência estabelecidas pelo padrão culto da linguagem.","content_fingerprint":"observe o trecho o emprego do sinal indicativo de crase em as necessidades l 12 e obrigatorio a omissao desse sinal provocaria erro gramatical por desrespeitar as regras de regencia estabelecidas pelo padrao culto da linguagem","audit":{"id":"76cca2fd-7671-59b6-9559-17725a0c768a","document_sha256":"ab4c99104c3359eb63ac78984c24d75be4e967a7f75e5b46f855efbdb1078a88","document_name":"12-03_lingua_portuguesa_giancarla_bombonato.pdf","source_page":4,"item_number":2,"extracted_statement":"Observe o trecho: O emprego do sinal indicativo de crase em “às necessidades” (L.12) é obrigatório; a omissão desse sinal provocaria erro gramatical por desrespeitar as regras de regência estabelecidas pelo padrão culto da linguagem.","provided_answer":"E","current_answer":null,"review_status":"needs_review","review_note":"O gabarito de crase ou o recorte extraído exige conciliação; não aceitar automaticamente a chave antiga sem o trecho e condições completos.","question_table":null,"question_id":null,"reviewed_at":null,"reviewed_by":null},"question":null},{"input_index":132,"statement":"Os indivíduos, evidentemente, não existem à margem da sociedade. O sinal indicativo de crase em “à margem” indica que o sentido com que está empregado o verbo existir exige a preposição a na sua complementação.","content_fingerprint":"os individuos evidentemente nao existem a margem da sociedade o sinal indicativo de crase em a margem indica que o sentido com que esta empregado o verbo existir exige a preposicao a na sua complementacao","audit":{"id":"baa825eb-855d-5819-9e4b-748a78a8026b","document_sha256":"49731cfb6bfccde985deb7c5f0d1c3c3c762bc7a5853b1a684a0098b0b5153de","document_name":"12-04_lingua_portuguesa_giancarla_bombonato.pdf","source_page":3,"item_number":1,"extracted_statement":"Os indivíduos, evidentemente, não existem à margem da sociedade. O sinal indicativo de crase em “à margem” indica que o sentido com que está empregado o verbo existir exige a preposição a na sua complementação.","provided_answer":"E","current_answer":"E","review_status":"published","review_note":"Texto suficiente, alternativas e chave revistos por análise linguística assistida; adaptação delimitada e origem didática explícita.","question_table":"curated_question_catalog","question_id":"3fc86116-5cb6-5a88-8f77-c3229563bc7b","reviewed_at":"2026-10-25T03:23:26.419620+00:00","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6"},"question":{"id":"3fc86116-5cb6-5a88-8f77-c3229563bc7b","source_id":"1e2fd682-059c-5a08-b8ed-416cc61441fc","syllabus_topic_id":"5873244d-48e6-4241-a474-b5db3317d27f","external_item_key":"didactic:49731cfb6bfccde985deb7c5f0d1c3c3c762bc7