create function pg_temp.didactic_norm(v text) returns text language sql immutable as $$
 select btrim(regexp_replace(translate(lower(regexp_replace(coalesce(v,''),'([[:alnum:]])-[[:space:]]+([[:alnum:]])','\1\2','g')),
 'áàâãäåéèêëíìîïóòôõöúùûüçñ','aaaaaaeeeeiiiiooooouuuucn'),'[^a-z0-9]+',' ','g'))
$$;
create temp table didactic_existing on commit drop as
 select pg_temp.didactic_norm(q.question_text) as fingerprint from public.curated_question_catalog q where q.subject='Língua Portuguesa'
 union all select pg_temp.didactic_norm(q.stem) from public.board_exam_questions q where q.subject='Língua Portuguesa' and coalesce(q.support_text,'')='' and coalesce(q.options,'{}'::jsonb) in ('{}'::jsonb,'[]'::jsonb) and coalesce(to_jsonb(q.figure_urls),'[]'::jsonb)='[]'::jsonb
 union all select pg_temp.didactic_norm(q.question_text) from public.official_exam_questions q where q.subject='Língua Portuguesa' and q.support_text_id is null;
create index on didactic_existing using hash(fingerprint);
do $guard$
declare p jsonb;r jsonb;existing public.curated_question_catalog;old public.didactic_question_imports;has_existing boolean;
begin
 select payload into p from didactic_payload;
 if not exists(select 1 from public.user_roles where user_id=(p->>'actor')::uuid and role::text='admin') then raise exception 'Responsável de publicação não é administrador.'; end if;
 if not exists(select 1 from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where t.id=(p#>>'{topic,id}')::uuid and t.content_status='current' and e.status='active' and t.topic_text=p#>>'{topic,topic_text}') then raise exception 'Tópico de edital não está atual.'; end if;
 if exists(select 1 from jsonb_array_elements(p->'sources') s left join public.content_sources c on c.id=(s->>'id')::uuid where c.id is null or not c.is_official or c.status<>'vigente' or c.url<>s->>'url') then raise exception 'Fonte oficial deixou de estar verificada.'; end if;
 for r in select value from jsonb_array_elements(p->'rows') loop
  select * into old from public.didactic_question_imports where document_sha256=r#>>'{audit,document_sha256}' and item_number=(r#>>'{audit,item_number}')::integer for update;
  if found and (not(to_jsonb(old) @> ((r->'audit')-'reviewed_at')) or old.reviewed_at is distinct from (r#>>'{audit,reviewed_at}')::timestamptz) then raise exception 'Importação anterior diferente; revisar sem sobrescrever.'; end if;
  if r->'question'<>'null'::jsonb then
   if not exists(select 1 from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where t.id=(r#>>'{question,syllabus_topic_id}')::uuid and t.content_status='current' and e.status='active') then raise exception 'Tópico da questão não está ativo.'; end if;
   if r#>>'{audit,review_status}'<>'published' or r#>>'{question,didactic_provenance,origin}'<>'didactic_material' or r#>>'{question,content_status}'<>'active' or r#>>'{question,exam_board}'<>'Material didático' then raise exception 'Classificação inválida.'; end if;
   if not exists(select 1 from public.study_materials m where m.slug=r#>>'{question,didactic_provenance,materialSlug}' and m.content_status='active') then raise exception 'Material de apoio indisponível.'; end if;
   select * into existing from public.curated_question_catalog where id=(r#>>'{question,id}')::uuid for update;
   has_existing=found;
   if has_existing and (not(to_jsonb(existing) @> ((r->'question')-'verified_at'-'law_version_checked_at')) or existing.verified_at<>(r#>>'{question,verified_at}')::timestamptz or existing.law_version_checked_at<>(r#>>'{question,law_version_checked_at}')::timestamptz) then raise exception 'Questão existente diferente.'; end if;
   if not has_existing and exists(select 1 from didactic_existing where fingerprint=r->>'content_fingerprint') then raise exception 'Conteúdo equivalente cadastrado em concorrência; reutilizar em vez de duplicar.'; end if;
  elsif r#>>'{audit,review_status}' in ('needs_review','obsolete') and (r#>>'{audit,current_answer}' is not null or r#>>'{audit,question_id}' is not null) then raise exception 'Item pendente não pode ser liberado para treino.';
  end if;
 end loop;
end $guard$;
insert into public.curated_question_catalog(id,source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,verified_at,law_version_checked_at,didactic_provenance)
select q.id,q.source_id,q.syllabus_topic_id,q.external_item_key,q.contest_name,q.contest_year,q.career_name,q.exam_board,q.subject,q.subtopic,q.tested_topic,q.question_text,q.official_answer,q.explanation,q.legal_basis,q.difficulty,q.content_status,q.is_original,q.verified_at,q.law_version_checked_at,q.didactic_provenance from didactic_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.curated_question_catalog,r->'question') q where r->'question'<>'null'::jsonb on conflict(source_id,external_item_key) do nothing;
insert into public.didactic_question_imports(id,document_sha256,document_name,source_page,item_number,extracted_statement,provided_answer,current_answer,review_status,review_note,question_table,question_id,reviewed_at,reviewed_by)
select d.id,d.document_sha256,d.document_name,d.source_page,d.item_number,d.extracted_statement,d.provided_answer,d.current_answer,d.review_status,d.review_note,d.question_table,d.question_id,d.reviewed_at,d.reviewed_by from didactic_payload p cross join lateral jsonb_array_elements(p.payload->'rows') r cross join lateral jsonb_populate_record(null::public.didactic_question_imports,r->'audit') d on conflict(document_sha256,item_number) do nothing;
do $verify$
declare p jsonb;r jsonb;matched boolean;
begin
 select payload into p from didactic_payload;
 for r in select value from jsonb_array_elements(p->'rows') loop
  if not exists(select 1 from public.didactic_question_imports d where d.id=(r#>>'{audit,id}')::uuid and d.review_status=r#>>'{audit,review_status}' and d.extracted_statement=r#>>'{audit,extracted_statement}') then raise exception 'Falha na conferência da classificação.'; end if;
  if r#>>'{audit,review_status}' in ('published','duplicate_reused') then
   if r#>>'{audit,question_table}'='curated_question_catalog' then select exists(select 1 from public.curated_question_catalog q where q.id=(r#>>'{audit,question_id}')::uuid and q.content_status='active' and q.official_answer=r#>>'{audit,current_answer}') into matched;
   elsif r#>>'{audit,question_table}'='board_exam_questions' then select exists(select 1 from public.board_exam_questions q where q.id=(r#>>'{audit,question_id}')::uuid and q.content_status='active' and q.official_answer=r#>>'{audit,current_answer}') into matched;
   else select exists(select 1 from public.official_exam_questions q where q.id=(r#>>'{audit,question_id}')::uuid and q.content_status='active' and q.official_answer=r#>>'{audit,current_answer}') into matched; end if;
   if not matched then raise exception 'Questão de treino não encontrada ou gabarito divergente.'; end if;
  end if;
  if r->'question'<>'null'::jsonb and not exists(select 1 from public.curated_question_catalog q where q.id=(r#>>'{question,id}')::uuid and q.question_text=r#>>'{question,question_text}' and q.explanation=r#>>'{question,explanation}' and q.didactic_provenance=r#>'{question,didactic_provenance}' and q.legal_basis=r#>'{question,legal_basis}') then raise exception 'Falha na leitura final da questão.'; end if;
 end loop;
end $verify$;
select d.review_status,count(*) as count from public.didactic_question_imports d join didactic_payload p on true
where d.id in(select (r#>>'{audit,id}')::uuid from jsonb_array_elements(p.payload->'rows') r) group by d.review_status order by d.review_status;
commit;
